import { clampPageIndex } from './normalize'
import { capabilitiesEqual, DEFAULT_CAPABILITIES } from './capabilities'
import type {
  BookPreviewAppearance,
  BookPreviewCapabilities,
  BookPreviewContentsEntry,
  BookPreviewError,
  BookPreviewMode,
  BookPreviewStatus,
} from './types'

export type BookPreviewState = {
  mode: BookPreviewMode
  pageIndex: number
  totalPages: number
  appearance: BookPreviewAppearance
  sound: boolean
  status: BookPreviewStatus
  error: BookPreviewError | null
  capabilities: BookPreviewCapabilities
  /** Engine-supplied table of contents (e.g. a PDF outline); empty when the
      document does not provide one. */
  contents: BookPreviewContentsEntry[]
  engineEpoch: number
}

export type BookPreviewAction =
  | { type: 'hydrate'; state: Partial<BookPreviewState> }
  | { type: 'set-mode'; mode: BookPreviewMode }
  | { type: 'set-page'; pageIndex: number }
  | { type: 'next-page' }
  | { type: 'prev-page' }
  | { type: 'set-appearance'; appearance: BookPreviewAppearance }
  | { type: 'set-sound'; sound: boolean }
  | { type: 'engine-loading' }
  | {
      type: 'engine-ready'
      totalPages: number
      capabilities: BookPreviewCapabilities
      contents?: BookPreviewContentsEntry[]
    }
  | { type: 'engine-error'; error: BookPreviewError }
  | { type: 'engine-unsupported'; message: string }
  | { type: 'empty' }
  | { type: 'retry' }
  | { type: 'reset-source'; pageIndex?: number }

export function createInitialState(input: {
  mode: BookPreviewMode
  pageIndex: number
  appearance: BookPreviewAppearance
  sound: boolean
}): BookPreviewState {
  return {
    mode: input.mode,
    pageIndex: input.pageIndex,
    totalPages: 0,
    appearance: input.appearance,
    sound: input.sound,
    status: 'idle',
    error: null,
    capabilities: DEFAULT_CAPABILITIES,
    contents: [],
    engineEpoch: 0,
  }
}

function contentsEqual(
  left: BookPreviewContentsEntry[],
  right: BookPreviewContentsEntry[],
): boolean {
  if (left === right) return true
  if (left.length !== right.length) return false
  return left.every(
    (entry, index) =>
      entry.title === right[index]?.title &&
      entry.pageIndex === right[index]?.pageIndex &&
      entry.depth === right[index]?.depth,
  )
}

export function bookPreviewReducer(
  state: BookPreviewState,
  action: BookPreviewAction,
): BookPreviewState {
  switch (action.type) {
    case 'hydrate':
      return { ...state, ...action.state }
    case 'set-mode':
      if (action.mode === state.mode && state.status !== 'unsupported') {
        return state
      }
      return {
        ...state,
        mode: action.mode,
        status: 'loading',
        error: null,
        engineEpoch: state.engineEpoch + 1,
      }
    case 'set-page': {
      const pageIndex = clampPageIndex(
        action.pageIndex,
        Math.max(state.totalPages, 1),
      )
      if (pageIndex === state.pageIndex) return state
      return { ...state, pageIndex }
    }
    case 'next-page': {
      const pageIndex = clampPageIndex(state.pageIndex + 1, state.totalPages)
      if (pageIndex === state.pageIndex) return state
      return { ...state, pageIndex }
    }
    case 'prev-page': {
      const pageIndex = clampPageIndex(state.pageIndex - 1, state.totalPages)
      if (pageIndex === state.pageIndex) return state
      return { ...state, pageIndex }
    }
    case 'set-appearance':
      if (action.appearance === state.appearance) return state
      return { ...state, appearance: action.appearance }
    case 'set-sound':
      if (action.sound === state.sound) return state
      return { ...state, sound: action.sound }
    case 'engine-loading':
      if (state.status === 'loading' && state.error === null) return state
      return { ...state, status: 'loading', error: null }
    case 'engine-ready': {
      const totalPages = Math.max(0, action.totalPages)
      const status = 'ready'
      const pageIndex = clampPageIndex(state.pageIndex, totalPages)
      const contents = action.contents ?? []
      if (
        state.status === status &&
        state.error === null &&
        state.totalPages === totalPages &&
        state.pageIndex === pageIndex &&
        contentsEqual(state.contents, contents) &&
        capabilitiesEqual(state.capabilities, action.capabilities)
      ) {
        return state
      }
      return {
        ...state,
        status,
        error: null,
        totalPages,
        pageIndex,
        capabilities: action.capabilities,
        // Reuse the previous array when nothing changed so subscribers are
        // not re-rendered by repeated ready reports.
        contents: contentsEqual(state.contents, contents)
          ? state.contents
          : contents,
      }
    }
    case 'engine-error':
      return {
        ...state,
        status: 'error',
        error: action.error,
      }
    case 'engine-unsupported':
      return {
        ...state,
        status: 'unsupported',
        error: { kind: 'unsupported', message: action.message },
      }
    case 'empty':
      return {
        ...state,
        status: 'empty',
        error: {
          kind: 'empty',
          message: 'No pages or document are available to preview.',
        },
        totalPages: 0,
        pageIndex: 0,
        contents: [],
      }
    case 'retry':
      return {
        ...state,
        status: 'loading',
        error: null,
        engineEpoch: state.engineEpoch + 1,
      }
    case 'reset-source':
      return {
        ...state,
        pageIndex: action.pageIndex ?? 0,
        totalPages: 0,
        status: 'loading',
        error: null,
        contents: [],
      }
    default:
      return state
  }
}

import {
  bookPreviewReducer,
  type BookPreviewAction,
  type BookPreviewState,
} from './reducer'
import type { BookPreviewError, BookPreviewStatus } from './types'

export type PreviewListeners = {
  onStatusChange?: (status: BookPreviewStatus) => void
  onError?: (error: BookPreviewError) => void
}

// External store around the reducer. State swaps are atomic so subscribers get
// a stable snapshot for useSyncExternalStore, and prop notifications fire
// inside dispatch — transactionally with the transition that produced them —
// instead of a post-commit effect.
export function createPreviewStore(initial: BookPreviewState) {
  let state = initial
  const subscribers = new Set<() => void>()
  let listeners: PreviewListeners = {}
  return {
    getState: () => state,
    subscribe(listener: () => void) {
      subscribers.add(listener)
      return () => {
        subscribers.delete(listener)
      }
    },
    dispatch(action: BookPreviewAction) {
      const next = bookPreviewReducer(state, action)
      if (next === state) return
      const prev = state
      state = next
      if (next.status !== prev.status) listeners.onStatusChange?.(next.status)
      if (next.error && next.error !== prev.error)
        listeners.onError?.(next.error)
      for (const listener of subscribers) listener()
    },
    setListeners(next: PreviewListeners) {
      listeners = next
    },
    // Replays the current snapshot to freshly registered handlers, matching the
    // mount + identity-change emissions a dep-driven effect would produce.
    emitCurrent() {
      listeners.onStatusChange?.(state.status)
      if (state.error) listeners.onError?.(state.error)
    },
  }
}

export type PreviewStore = ReturnType<typeof createPreviewStore>

import type {
  BookPreviewPage,
  BookPreviewSource,
  NormalizedBookSource,
} from './types'

function pageId(page: BookPreviewPage, index: number): string {
  if (page.id.trim().length > 0) return page.id
  return `page-${page.pageNumber || index + 1}`
}

export function normalizePages(
  pages: BookPreviewPage[] | undefined,
): BookPreviewPage[] {
  if (!pages || pages.length === 0) return []
  return pages.map((page, index) => ({
    ...page,
    id: pageId(page, index),
    pageNumber: page.pageNumber > 0 ? page.pageNumber : index + 1,
    paragraphs: page.paragraphs?.filter(
      (paragraph) => paragraph.trim().length > 0,
    ),
  }))
}

export function normalizeSource(
  source: BookPreviewSource,
): NormalizedBookSource {
  const pages = normalizePages(source.pages)
  const pdfUrl = source.pdfUrl?.trim() || undefined
  const downloadUrl = source.downloadUrl?.trim() || pdfUrl

  return {
    revision: source.revision?.trim() || undefined,
    title: source.title?.trim() || undefined,
    author: source.author?.trim() || undefined,
    pages,
    pdfUrl,
    pdfFileName: source.pdfFileName?.trim() || undefined,
    allowPdfUpload: Boolean(source.allowPdfUpload),
    downloadUrl,
    downloadFileName:
      source.downloadFileName?.trim() ||
      source.pdfFileName?.trim() ||
      undefined,
  }
}

function hashIdentity(value: string): string {
  let hash = 2166136261
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index)
    hash = Math.imul(hash, 16777619)
  }
  return (hash >>> 0).toString(36)
}

export function sourceIdentity(source: NormalizedBookSource): string {
  const serializable = {
    revision: source.revision,
    title: source.title,
    author: source.author,
    pdfUrl: source.pdfUrl,
    pdfFileName: source.pdfFileName,
    allowPdfUpload: source.allowPdfUpload,
    pages: source.pages.map((page) => {
      const serializablePage = { ...page }
      delete serializablePage.render
      return serializablePage
    }),
  }
  return hashIdentity(JSON.stringify(serializable))
}

export function pageSearchText(page: BookPreviewPage): string {
  if (page.searchableText) return page.searchableText
  return [
    page.title,
    page.subtitle,
    page.kicker,
    ...(page.paragraphs ?? []),
    page.quote?.text,
    page.quote?.attribution,
  ]
    .filter(Boolean)
    .join(' ')
}

export function clampPageIndex(pageIndex: number, totalPages: number): number {
  if (totalPages <= 0) return 0
  if (!Number.isFinite(pageIndex)) return 0
  return Math.min(Math.max(0, Math.trunc(pageIndex)), totalPages - 1)
}

export function isEmptySource(source: NormalizedBookSource): boolean {
  return source.pages.length === 0 && !source.pdfUrl && !source.allowPdfUpload
}

import { BOOK_PREVIEW_APPEARANCES, BOOK_PREVIEW_MODES } from './types'
import type { BookPreviewAppearance, BookPreviewMode } from './types'
import { sanitizeTypography, type BookPreviewTypography } from './typography'

export const PREMIER_VIEWS = [
  'book',
  'single',
  'spread',
  'scroll',
  'text',
] as const
export type PremierView = (typeof PREMIER_VIEWS)[number]

export type BookPreviewPrefs = {
  appearance?: BookPreviewAppearance
  mode?: BookPreviewMode
  /** PDF reader zoom — 0 is the fit-width sentinel used by the pdf engine. */
  pdfZoom?: number
  /** The premier reader's layout — book flip, one page, a spread, or a
      continuous strip. */
  premierView?: PremierView
  /** The "Aa" reading settings — type size, face, spacing, measure. */
  typography?: BookPreviewTypography
}

const PREFS_KEY = 'book-preview:prefs'

export function readBookPreviewPrefs(): BookPreviewPrefs {
  if (typeof window === 'undefined') return {}
  try {
    const raw = window.localStorage.getItem(PREFS_KEY)
    if (!raw) return {}
    const parsed = JSON.parse(raw) as Partial<
      Record<keyof BookPreviewPrefs, unknown>
    >
    const prefs: BookPreviewPrefs = {}
    if (
      typeof parsed.appearance === 'string' &&
      (BOOK_PREVIEW_APPEARANCES as readonly string[]).includes(
        parsed.appearance,
      )
    ) {
      prefs.appearance = parsed.appearance as BookPreviewAppearance
    }
    if (
      typeof parsed.mode === 'string' &&
      (BOOK_PREVIEW_MODES as readonly string[]).includes(parsed.mode)
    ) {
      prefs.mode = parsed.mode as BookPreviewMode
    }
    if (typeof parsed.pdfZoom === 'number' && Number.isFinite(parsed.pdfZoom)) {
      prefs.pdfZoom = parsed.pdfZoom
    }
    if (
      typeof parsed.premierView === 'string' &&
      (PREMIER_VIEWS as readonly string[]).includes(parsed.premierView)
    ) {
      prefs.premierView = parsed.premierView as PremierView
    }
    if (parsed.typography !== undefined) {
      prefs.typography = sanitizeTypography(parsed.typography)
    }
    return prefs
  } catch {
    // localStorage may be unavailable (private mode, sandboxed iframe).
    return {}
  }
}

// Merges into the existing record — the shell and the engines write different
// keys of the same object and must not clobber each other.
export function writeBookPreviewPrefs(patch: BookPreviewPrefs): void {
  if (typeof window === 'undefined') return
  try {
    const next = { ...readBookPreviewPrefs(), ...patch }
    window.localStorage.setItem(PREFS_KEY, JSON.stringify(next))
  } catch {
    // localStorage may be unavailable.
  }
}

import type { BookPreviewCapabilities } from './types'

export const DEFAULT_CAPABILITIES: BookPreviewCapabilities = {
  pagination: true,
  spreads: false,
  curl: false,
  zoom: false,
  loupe: false,
  search: false,
  speech: false,
  fullscreen: true,
  download: false,
  upload: false,
  appearance: true,
  sound: true,
  thumbnails: false,
  webgl: false,
}

export function mergeCapabilities(
  base: BookPreviewCapabilities,
  patch: Partial<BookPreviewCapabilities>,
): BookPreviewCapabilities {
  return { ...base, ...patch }
}

export function capabilitiesEqual(
  left: BookPreviewCapabilities,
  right: BookPreviewCapabilities,
): boolean {
  const keys = Object.keys(left) as Array<keyof BookPreviewCapabilities>
  return keys.every((key) => left[key] === right[key])
}

let webglSupport: boolean | null = null

export function hasWebGLSupport(): boolean {
  if (typeof document === 'undefined') return false
  if (webglSupport !== null) return webglSupport
  try {
    const canvas = document.createElement('canvas')
    webglSupport = Boolean(
      canvas.getContext('webgl2') ||
      canvas.getContext('webgl') ||
      canvas.getContext('experimental-webgl'),
    )
    return webglSupport
  } catch {
    webglSupport = false
    return false
  }
}

export function hasSpeechSupport(): boolean {
  return typeof window !== 'undefined' && 'speechSynthesis' in window
}

export function hasFullscreenSupport(): boolean {
  return typeof document !== 'undefined' && Boolean(document.fullscreenEnabled)
}

export function hasAudioSupport(): boolean {
  if (typeof window === 'undefined') return false
  const AudioContextClass =
    window.AudioContext ||
    (window as Window & { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext
  return Boolean(AudioContextClass)
}

import { isEmptySource } from './normalize'
import { DEFAULT_CAPABILITIES, hasWebGLSupport } from './capabilities'
import type {
  BookPreviewEngine,
  BookPreviewMode,
  NormalizedBookSource,
} from './types'

export const pageEngine: BookPreviewEngine = {
  id: 'page',
  label: 'Slide',
  description: 'Horizontal page slide',
  capabilities: {
    ...DEFAULT_CAPABILITIES,
    spreads: true,
    appearance: true,
    sound: true,
    fullscreen: true,
  },
  requiresPages: true,
  load: () => import('./engines/page-engine'),
}

export function engineIsCompatible(
  engine: BookPreviewEngine,
  source: NormalizedBookSource,
): boolean {
  if (engine.requiresPages && source.pages.length === 0) return false
  // The pdf engine alone may sit behind `allowPdfUpload`: it renders the
  // upload affordance itself. The document-backed modes below have no empty
  // state, so they only become compatible once a real pdfUrl exists.
  if (engine.requiresPdf && !source.pdfUrl && !source.allowPdfUpload)
    return false
  // These engines render either page data or a rasterized PDF, so they need
  // at least one of the two.
  if (
    (engine.id === 'curl' ||
      engine.id === 'scroll' ||
      engine.id === 'archival-curl') &&
    source.pages.length === 0 &&
    !source.pdfUrl
  ) {
    return false
  }
  // The flagship renders its own upload affordance, so like the pdf engine it
  // stays compatible on an upload-only source.
  if (
    engine.id === 'premier' &&
    source.pages.length === 0 &&
    !source.pdfUrl &&
    !source.allowPdfUpload
  ) {
    return false
  }
  return true
}

export function resolveEnabledEngines(
  engines: BookPreviewEngine[] | undefined,
  enabledModes: BookPreviewMode[] | undefined,
): BookPreviewEngine[] {
  const catalog = engines && engines.length > 0 ? engines : [pageEngine]
  if (!enabledModes || enabledModes.length === 0) {
    return catalog.filter(
      (engine, index, list) =>
        list.findIndex((item) => item.id === engine.id) === index,
    )
  }
  const allowed = new Set(enabledModes)
  return catalog.filter((engine) => allowed.has(engine.id))
}

export function resolveCompatibleEngines(
  engines: BookPreviewEngine[],
  source: NormalizedBookSource,
): BookPreviewEngine[] {
  return engines.filter((engine) => engineIsCompatible(engine, source))
}

// When the requested mode cannot render a source, the reader should land on
// the mode that fits the document — not whatever happens to be first in the
// engine catalog. PDFs want the real document reader (selectable text, zoom,
// bounded memory) with continuous scroll as the runner-up; page data wants
// the dependency-free slide engine.
const FALLBACK_MODE_ORDER = {
  pdf: ['pdf', 'scroll', 'page'],
  pages: ['page'],
} as const satisfies Record<string, readonly BookPreviewMode[]>

export function resolveActiveEngine(input: {
  requestedMode: BookPreviewMode | undefined
  engines: BookPreviewEngine[]
  source: NormalizedBookSource
}): {
  engine: BookPreviewEngine | null
  fallback: boolean
  unsupported: boolean
} {
  const { requestedMode, engines, source } = input
  if (isEmptySource(source)) {
    return { engine: null, fallback: false, unsupported: false }
  }

  const compatible = resolveCompatibleEngines(engines, source)
  const byId = new Map(compatible.map((engine) => [engine.id, engine]))
  const requested = requestedMode ? byId.get(requestedMode) : undefined

  if (requested) {
    return { engine: requested, fallback: false, unsupported: false }
  }

  const preference =
    source.pages.length > 0
      ? FALLBACK_MODE_ORDER.pages
      : FALLBACK_MODE_ORDER.pdf
  for (const id of preference) {
    const engine = byId.get(id)
    if (engine) {
      return { engine, fallback: Boolean(requestedMode), unsupported: false }
    }
  }
  if (compatible[0]) {
    return {
      engine: compatible[0],
      fallback: Boolean(requestedMode),
      unsupported: false,
    }
  }
  return { engine: null, fallback: false, unsupported: true }
}

export function createWebGLSupportCheck(): () => boolean {
  return hasWebGLSupport
}

export function describeEngineLoadFailure(label: string): string {
  return `The ${label} reader failed to load. Reload the page, then try this mode again.`
}

export function shouldPrefetchEngines(): boolean {
  // A failed dynamic import is cached for the page lifetime. Prefetching in
  // development races Turbopack HMR and can permanently poison a mode until reload.
  return process.env.NODE_ENV === 'production'
}

export { pageEngine as defaultEngine }

type EditableLike = {
  tagName?: string
  isContentEditable?: boolean
  closest?: (selector: string) => unknown
}

function asElement(target: EventTarget | null): EditableLike | null {
  if (!target || typeof target !== 'object') return null
  if (!('tagName' in target) && !('isContentEditable' in target)) return null
  return target as EditableLike
}

export function isEditableTarget(target: EventTarget | null): boolean {
  const element = asElement(target)
  if (!element) return false
  if (element.isContentEditable) return true
  const tag = element.tagName?.toUpperCase()
  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return true
  return Boolean(
    element.closest?.("[contenteditable='true'], [role='textbox']"),
  )
}

const INTERACTIVE_SELECTOR = [
  'a[href]',
  'button',
  'input',
  'select',
  'textarea',
  "[contenteditable='true']",
  "[role='button']",
  "[role='checkbox']",
  "[role='combobox']",
  "[role='link']",
  "[role='menuitem']",
  "[role='option']",
  "[role='radio']",
  "[role='slider']",
  "[role='spinbutton']",
  "[role='switch']",
  "[role='tab']",
  "[role='textbox']",
].join(',')

export function isInteractiveTarget(target: EventTarget | null): boolean {
  const element = asElement(target)
  if (!element) return false
  const tag = element.tagName?.toUpperCase()
  if (
    tag === 'A' ||
    tag === 'BUTTON' ||
    tag === 'INPUT' ||
    tag === 'SELECT' ||
    tag === 'TEXTAREA'
  ) {
    return true
  }
  return Boolean(element.closest?.(INTERACTIVE_SELECTOR))
}

export function isReaderKeyboardEvent(
  event: KeyboardEvent,
  root: HTMLElement | null,
): boolean {
  if (!root) return false
  if (isInteractiveTarget(event.target) && event.target !== root) return false
  const active = document.activeElement
  if (
    active instanceof HTMLElement &&
    !root.contains(active) &&
    active !== root
  ) {
    return false
  }
  return (
    root.contains(event.target instanceof Node ? event.target : null) ||
    active === root ||
    root.contains(active)
  )
}

'use client'

import { useCallback, useEffect, useState, useSyncExternalStore } from 'react'
import { hasFullscreenSupport } from './capabilities'

function useMediaQuery(query: string): boolean {
  const subscribe = useCallback(
    (onChange: () => void) => {
      if (
        typeof window === 'undefined' ||
        typeof window.matchMedia !== 'function'
      ) {
        return () => {}
      }
      const media = window.matchMedia(query)
      media.addEventListener('change', onChange)
      return () => media.removeEventListener('change', onChange)
    },
    [query],
  )
  const getSnapshot = useCallback(() => {
    if (
      typeof window === 'undefined' ||
      typeof window.matchMedia !== 'function'
    ) {
      return false
    }
    return window.matchMedia(query).matches
  }, [query])
  return useSyncExternalStore(subscribe, getSnapshot, () => false)
}

export function usePrefersReducedMotion(): boolean {
  return useMediaQuery('(prefers-reduced-motion: reduce)')
}

export function usePrefersReducedTransparency(): boolean {
  return useMediaQuery('(prefers-reduced-transparency: reduce)')
}

export function usePrefersMoreContrast(): boolean {
  return useMediaQuery('(prefers-contrast: more)')
}

export function useFinePointer(): boolean {
  return useMediaQuery('(hover: hover) and (pointer: fine)')
}

export function useNarrowLayout(): boolean {
  return useMediaQuery('(max-width: 40rem)')
}

export function useCoarsePointer(): boolean {
  return useMediaQuery('(pointer: coarse)')
}

export function useFullscreenSupport(): boolean {
  // Static per page load — no subscription needed. Server snapshot is false so
  // SSR/hydration never renders a fullscreen affordance that can't work.
  return useSyncExternalStore(
    () => () => {},
    () => hasFullscreenSupport(),
    () => false,
  )
}

export function useDocumentVisible(): boolean {
  const [visible, setVisible] = useState(true)

  useEffect(() => {
    const update = () => setVisible(document.visibilityState === 'visible')
    update()
    document.addEventListener('visibilitychange', update)
    return () => document.removeEventListener('visibilitychange', update)
  }, [])

  return visible
}

let sharedContext: AudioContext | null = null

function getAudioContext(): AudioContext | null {
  if (typeof window === 'undefined') return null
  const AudioContextClass =
    window.AudioContext ||
    (window as Window & { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext
  if (!AudioContextClass) return null
  if (!sharedContext || sharedContext.state === 'closed') {
    try {
      sharedContext = new AudioContextClass()
    } catch {
      return null
    }
  }
  // Browsers suspend contexts created before a user gesture; resume on play.
  if (sharedContext.state === 'suspended') void sharedContext.resume()
  return sharedContext
}

const PAGE_TURN_DURATION = 0.22
let cachedNoise: AudioBuffer | null = null

// The noise burst is identical every turn, so synthesising ~10k samples per
// page flip is pure main-thread waste. Build it once per context instead.
function getPageTurnBuffer(context: AudioContext): AudioBuffer {
  if (cachedNoise && cachedNoise.sampleRate === context.sampleRate) {
    return cachedNoise
  }
  const bufferSize = Math.floor(context.sampleRate * PAGE_TURN_DURATION)
  const buffer = context.createBuffer(1, bufferSize, context.sampleRate)
  const output = buffer.getChannelData(0)
  for (let i = 0; i < bufferSize; i += 1) {
    output[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufferSize * 0.4))
  }
  cachedNoise = buffer
  return buffer
}

export function playPageTurnSound(): void {
  const context = getAudioContext()
  if (!context) return

  const duration = PAGE_TURN_DURATION
  const buffer = getPageTurnBuffer(context)

  const whiteNoise = context.createBufferSource()
  whiteNoise.buffer = buffer

  const filter = context.createBiquadFilter()
  filter.type = 'bandpass'
  filter.frequency.setValueAtTime(650, context.currentTime)
  filter.frequency.exponentialRampToValueAtTime(
    250,
    context.currentTime + duration,
  )
  filter.Q.setValueAtTime(1.5, context.currentTime)

  const gainNode = context.createGain()
  gainNode.gain.setValueAtTime(0.18, context.currentTime)
  gainNode.gain.exponentialRampToValueAtTime(
    0.001,
    context.currentTime + duration,
  )

  whiteNoise.connect(filter)
  filter.connect(gainNode)
  gainNode.connect(context.destination)

  try {
    whiteNoise.start()
    whiteNoise.stop(context.currentTime + duration)
    whiteNoise.onended = () => {
      whiteNoise.disconnect()
      filter.disconnect()
      gainNode.disconnect()
    }
  } catch {
    // A suspended or closing context can reject start; the sound is optional.
  }
}

export function stopPageTurnSounds(): void {
  if (!sharedContext) return
  void sharedContext.close()
  sharedContext = null
  cachedNoise = null
}

.book-preview {
  --book-preview-ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --book-preview-press-ms: 160ms;
  --book-preview-press-scale: 0.97;
  --book-preview-ui-ms: 220ms;
  --book-preview-crossfade-ms: 180ms;
  --book-preview-surface: var(--card);
  --book-preview-surface-foreground: var(--card-foreground);
  /* The reader may be embedded in a sidebar or split view — container
     awareness lets future container queries size it by its own box rather
     than the viewport. */
  container-type: inline-size;
}

/* Reading typography ("Aa" settings). The shell writes these variables on
   the root; defaults here keep engines correct when rendered standalone. */
.book-preview {
  --bp-type-scale: 1;
  --bp-type-family:
    ui-serif, 'Iowan Old Style', 'Palatino Linotype', Palatino, Georgia, serif;
  --bp-type-leading: 1.7;
  --bp-type-measure: 40rem;
  --bp-type-align: start;
  --bp-type-tracking: normal;
}

.book-preview [data-bp-prose] {
  font-family: var(--bp-type-family);
  letter-spacing: var(--bp-type-tracking);
}

.book-preview [data-bp-prose] p {
  text-align: var(--bp-type-align);
  hyphens: auto;
  text-wrap: pretty;
}

/* Reflowable text (the premier Text view) takes size and leading too; fixed
   leaves keep their own size so a page never overflows its paper. */
.book-preview [data-bp-reflow] {
  font-size: calc(1.0625rem * var(--bp-type-scale));
  line-height: var(--bp-type-leading);
}

/* Paper for pure-type surfaces (the premier Text view). */
.book-preview [data-bp-paper='light'] {
  background: #fdfdfc;
  color: #1c1917;
}
.book-preview [data-bp-paper='sepia'] {
  background: #fbf0d9;
  color: #2c2523;
}
.book-preview [data-bp-paper='dark'] {
  background: #27272a;
  color: #f4f4f5;
}
.book-preview [data-bp-paper='oled'] {
  background: #000;
  color: #e4e4e7;
}
.book-preview [data-bp-paper]:not([data-bp-paper='system']) [data-bp-reflow] {
  color: inherit;
}
.book-preview
  [data-bp-paper]:not([data-bp-paper='system'])
  [data-bp-annotate-skip] {
  color: inherit;
  opacity: 0.55;
}

.book-preview [data-book-preview-press]:not(:disabled):active {
  transform: scale(var(--book-preview-press-scale));
}

.book-preview [data-book-preview-press] {
  transition: transform var(--book-preview-press-ms)
    var(--book-preview-ease-out);
}

.book-preview [data-book-preview-fade] {
  transition:
    opacity var(--book-preview-crossfade-ms) var(--book-preview-ease-out),
    transform var(--book-preview-crossfade-ms) var(--book-preview-ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .book-preview [data-book-preview-hover]:not(:disabled):hover {
    transform: translateY(-1px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .book-preview [data-book-preview-press],
  .book-preview [data-book-preview-fade],
  .book-preview [data-book-preview-hover] {
    transition:
      opacity 160ms linear,
      color 160ms linear,
      background-color 160ms linear,
      border-color 160ms linear;
    transform: none;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .book-preview [data-book-preview-surface] {
    background-color: var(--card);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
}

@media (prefers-contrast: more) {
  .book-preview [data-book-preview-surface] {
    border-width: 2px;
    background-color: var(--card);
  }
}

.book-preview [data-book-preview-curl],
.book-preview [data-book-preview-curl] .stf__parent,
.book-preview [data-book-preview-curl] .stf__item {
  overflow: visible;
}

.book-preview [data-book-preview-curl] .stf__parent,
.book-preview [data-book-preview-curl] .stf__block,
.book-preview [data-book-preview-curl] .stf__item {
  /* pan-y, not none: vertical gestures scroll the page past the reader,
     horizontal ones stay ours for the fold. With none, a phone-sized stage
     traps the scroll entirely. */
  touch-action: pan-y;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
}

.book-preview [data-book-preview-curl] .stf__block {
  cursor: grab;
}

.book-preview [data-book-preview-curl] .stf__block:active {
  cursor: grabbing;
}

.book-preview [data-book-preview-curl] .stf__item {
  background-color: var(--background);
  box-shadow:
    0 8px 24px hsl(0 0% 0% / 0.12),
    0 1px 0 hsl(0 0% 0% / 0.06);
}

/* Fill layout: the reader takes its parent's height instead of the inline
   breakpoint minimums, so app shells and reader routes get every pixel. */
.book-preview[data-layout='fill'] {
  height: 100%;
  min-height: 0;
}

.book-preview[data-layout='fill'] [data-book-preview-viewport] {
  min-height: 0;
  flex: 1 1 auto;
}

/* Immersive reading. The stage owns the whole screen; the toolbar and the
   pager float over it and slip away after a short idle (see
   use-immersive-chrome). Enter is ease-out 220ms, exit a touch quicker —
   the system responding should never feel slower than the reader asking. */
.book-preview[data-book-preview-immersive] {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: flex;
  width: 100%;
  height: 100dvh;
  max-width: none;
  flex-direction: column;
  gap: 0;
  padding: 0;
  overflow: hidden;
  border-radius: 0;
  background: var(--background);
}

.book-preview[data-book-preview-immersive] [data-book-preview-chrome] {
  position: absolute;
  left: max(0.5rem, env(safe-area-inset-left));
  right: max(0.5rem, env(safe-area-inset-right));
  z-index: 40;
  width: auto;
  border: 1px solid color-mix(in oklab, var(--border) 80%, transparent);
  border-radius: 0.875rem;
  background: color-mix(in oklab, var(--card) 82%, transparent);
  backdrop-filter: blur(16px) saturate(1.4);
  -webkit-backdrop-filter: blur(16px) saturate(1.4);
  box-shadow: 0 10px 30px -12px rgb(0 0 0 / 0.28);
  transition:
    opacity 220ms var(--book-preview-ease-out),
    transform 220ms var(--book-preview-ease-out);
}

.book-preview[data-book-preview-immersive] [data-book-preview-chrome='top'] {
  top: max(0.5rem, env(safe-area-inset-top));
}

.book-preview[data-book-preview-immersive] [data-book-preview-chrome='bottom'] {
  bottom: max(0.5rem, env(safe-area-inset-bottom));
  padding: 0.375rem 0.75rem 0.625rem;
}

.book-preview[data-chrome-hidden] [data-book-preview-chrome] {
  opacity: 0;
  pointer-events: none;
  transition-duration: 180ms;
}

.book-preview[data-chrome-hidden] [data-book-preview-chrome='top'] {
  transform: translateY(calc(-100% - 0.5rem));
}

.book-preview[data-chrome-hidden] [data-book-preview-chrome='bottom'] {
  transform: translateY(calc(100% + 0.5rem));
}

/* The cursor goes with the chrome — nothing on screen but the page. */
.book-preview[data-chrome-hidden] [data-book-preview-viewport] {
  cursor: none;
}

.book-preview[data-book-preview-immersive] [data-book-preview-viewport] {
  min-height: 0;
  flex: 1 1 auto;
  border: none;
  border-radius: 0;
  background: var(--background);
}

/* Engines frame their stage with padding and a card border inline; in
   fullscreen that frame is wasted screen. */
.book-preview[data-book-preview-immersive] [data-book-preview-engine-frame] {
  padding: 0;
  gap: 0;
}

.book-preview[data-book-preview-immersive] [data-book-preview-engine-stage] {
  border: none;
  border-radius: 0;
  background: transparent;
}

.book-preview[data-book-preview-immersive] [data-book-preview-scroll] {
  max-height: none;
  height: 100%;
}

.book-preview[data-book-preview-immersive] [data-book-preview-slide] {
  max-width: none;
}

.book-preview[data-book-preview-immersive]
  [data-book-preview-slide]
  > div
  > div {
  height: min(90svh, 60rem);
  width: min(38rem, 46vw);
}

/* Popups portal to <body> and must stack above the immersive reader, which
   itself sits above the host page. */
html[data-book-preview-immersive] body > [data-base-ui-portal] {
  position: relative;
  z-index: 90;
}

.book-preview:fullscreen {
  width: 100%;
  height: 100%;
  max-width: none;
  background: var(--background);
}

@media (prefers-reduced-motion: reduce) {
  .book-preview[data-chrome-hidden] [data-book-preview-chrome='top'],
  .book-preview[data-chrome-hidden] [data-book-preview-chrome='bottom'] {
    transform: none;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .book-preview[data-book-preview-immersive] [data-book-preview-chrome] {
    background: var(--card);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
}

/* Page-turn arrival: the incoming spread drifts in from the direction the
   leaf was pushed toward, so button, keyboard, and gesture navigation all
   land the same way.

   Paging is a high-frequency action. When turns arrive faster than this
   animation can finish -- a held arrow key, a dragged slider -- the engine
   sets data-instant and the page simply appears. Replaying a 220ms entrance
   ten times a second reads as flicker, not motion. */
.book-preview [data-book-preview-page] {
  opacity: 0;
  transform: translateX(var(--book-preview-enter-x, 0.75rem));
  transition:
    opacity var(--book-preview-ui-ms) var(--book-preview-ease-out),
    transform var(--book-preview-ui-ms) var(--book-preview-ease-out);
}

.book-preview [data-book-preview-page][data-enter-dir='prev'] {
  --book-preview-enter-x: -0.75rem;
}

.book-preview [data-book-preview-page][data-mounted] {
  opacity: 1;
  transform: translateX(0);
}

.book-preview [data-book-preview-page][data-instant] {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  /* Keep the fade for comprehension, drop the travel. */
  .book-preview [data-book-preview-page] {
    transform: none;
    transition: opacity 160ms linear;
  }
  .book-preview [data-book-preview-page][data-mounted] {
    transform: none;
  }
}

/* The PDF stage reuses the page-turn arrival, but animates `translate`
   rather than `transform` — pinch zoom owns transform on this element and
   the two would otherwise fight over the same property mid-gesture.
   Declared after the generic rules so equal-specificity overrides land. */
.book-preview [data-book-preview-pdf-stage][data-book-preview-page] {
  transform: none;
  translate: var(--book-preview-enter-x, 0.75rem) 0;
  transition:
    opacity var(--book-preview-ui-ms) var(--book-preview-ease-out),
    translate var(--book-preview-ui-ms) var(--book-preview-ease-out);
}

.book-preview
  [data-book-preview-pdf-stage][data-book-preview-page][data-mounted] {
  translate: 0 0;
}

.book-preview [data-book-preview-pdf-stage][data-instant] {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .book-preview [data-book-preview-pdf-stage][data-book-preview-page] {
    translate: none;
    transition: opacity 160ms linear;
  }
}

/* The resting curl book casts a soft shadow — page-flip draws shadows only
   while a leaf is in the air, so without this the book floats flat. */
.book-preview [data-book-preview-curl-book] {
  box-shadow:
    0 22px 44px -18px rgb(0 0 0 / 0.3),
    0 6px 14px -8px rgb(0 0 0 / 0.16);
}

/* Fore-edge page stacks. Thin repeating strips on each side of the book,
   width set per-side by the engine from the leaf count on that side. */
.book-preview [data-book-preview-curl-edge] {
  position: absolute;
  top: 4px;
  bottom: 4px;
  pointer-events: none;
  background: repeating-linear-gradient(
    to right,
    color-mix(in oklab, var(--foreground) 18%, transparent) 0 1px,
    transparent 1px 2.5px
  );
}

.book-preview [data-book-preview-curl-edge='prev'] {
  right: 100%;
}

.book-preview [data-book-preview-curl-edge='next'] {
  left: 100%;
}

/* A rasterized PDF leaf fades up as its bitmap lands, instead of snapping
   from skeleton to page. Driven by the src attribute so it works on the
   clones the flip book makes, which React never re-renders. */
.book-preview [data-book-preview-sheet-img] {
  opacity: 0;
  transition: opacity var(--book-preview-crossfade-ms)
    var(--book-preview-ease-out);
}

.book-preview [data-book-preview-sheet-img][src] {
  opacity: 1;
}

.book-preview
  :has(> [data-book-preview-sheet-img][src])
  > [data-book-preview-sheet-skeleton] {
  opacity: 0;
  transition: opacity var(--book-preview-crossfade-ms)
    var(--book-preview-ease-out);
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  .book-preview [data-book-preview-sheet-img] {
    transition-duration: 120ms;
  }
  .book-preview [data-book-preview-sheet-skeleton] {
    animation: none;
  }
}

/* Thumbnail grid entrance. Purely decorative, so it is opacity-and-lift only,
   never blocks pointer input, and is capped in the engine at ~12 steps. */
@keyframes book-preview-thumb-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.book-preview [data-book-preview-thumb] {
  animation: book-preview-thumb-in var(--book-preview-ui-ms)
    var(--book-preview-ease-out) var(--book-preview-thumb-delay, 0ms) both;
}

@media (prefers-reduced-motion: reduce) {
  .book-preview [data-book-preview-thumb] {
    animation: none;
  }
}

/* Highlight inks (::highlight rules) are injected at runtime by
   annotation-dom.ts — the build's CSS parser does not know the pseudo-element
   yet and would warn on every build. */

/* The selection card grows out of the passage it belongs to: anchored at
   the passage's centre, origin on the side facing the text, 160ms ease-out
   in. It is dismissed instantly — leaving should never make you wait. */
.book-preview [data-book-preview-annotation-card] {
  translate: -50% -100%;
  transform-origin: bottom center;
  transition:
    opacity 160ms var(--book-preview-ease-out),
    scale 160ms var(--book-preview-ease-out);
}

.book-preview [data-book-preview-annotation-card][data-placement='below'] {
  translate: -50% 0;
  transform-origin: top center;
}

@starting-style {
  .book-preview [data-book-preview-annotation-card] {
    opacity: 0;
    scale: 0.96;
  }
}

@media (prefers-reduced-motion: reduce) {
  .book-preview [data-book-preview-annotation-card] {
    transition: opacity 120ms linear;
  }
  @starting-style {
    .book-preview [data-book-preview-annotation-card] {
      scale: 1;
    }
  }
}

/* Notebook entries settle in with a short stagger the first time the sheet
   opens. The sheet portals out of the reader, so these are unscoped. */
[data-book-preview-notebook-item] {
  transition:
    opacity 200ms cubic-bezier(0.23, 1, 0.32, 1) var(--bp-stagger, 0ms),
    translate 200ms cubic-bezier(0.23, 1, 0.32, 1) var(--bp-stagger, 0ms);
}

@starting-style {
  [data-book-preview-notebook-item] {
    opacity: 0;
    translate: 0 6px;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-book-preview-notebook-item] {
    transition: opacity 120ms linear;
    translate: none;
  }
}

/* Drawing: a crosshair for the pen and marker, a cell for the eraser. The
   ink toolbar settles up from the page it belongs to. */
.book-preview [data-bp-ink-surface][data-tool='pen'],
.book-preview [data-bp-ink-surface][data-tool='marker'] {
  cursor: crosshair;
}

.book-preview [data-bp-ink-surface][data-tool='eraser'] {
  cursor: cell;
}

.book-preview [data-book-preview-ink-toolbar] {
  transition:
    opacity 200ms var(--book-preview-ease-out),
    translate 200ms var(--book-preview-ease-out);
}

@starting-style {
  .book-preview [data-book-preview-ink-toolbar] {
    opacity: 0;
    translate: -50% 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .book-preview [data-book-preview-ink-toolbar] {
    transition: opacity 120ms linear;
  }
}

/* A bookmarked page wears a ribbon that drops in from the top edge. */
.book-preview [data-book-preview-ribbon] {
  transition: translate 220ms var(--book-preview-ease-out);
}

@starting-style {
  .book-preview [data-book-preview-ribbon] {
    translate: 0 -100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .book-preview [data-book-preview-ribbon] {
    transition: none;
  }
}

/* Printing keeps only the page — chrome is UI, not content. */
@media print {
  .book-preview [data-book-preview-chrome],
  .book-preview [data-book-preview-progress] {
    display: none !important;
  }

  .book-preview [data-book-preview-viewport] {
    border: none;
    border-radius: 0;
    box-shadow: none;
    min-height: 0 !important;
  }
}

/* PDF.js text layer, scoped to this component.
   A faithful subset of pdfjs-dist/web/pdf_viewer.css -- importing the full
   viewer stylesheet would drag in thousands of lines of unrelated chrome.
   The spans are transparent and sit exactly over the canvas, so the page can
   be selected, copied, and found with the browser's own find. */
.book-preview .textLayer {
  position: absolute;
  inset: 0;
  overflow: clip;
  opacity: 1;
  line-height: 1;
  text-align: initial;
  letter-spacing: normal;
  word-spacing: normal;
  text-size-adjust: none;
  forced-color-adjust: none;
  transform-origin: 0 0;
  caret-color: CanvasText;
  z-index: 1;
  --min-font-size: 1;
  --text-scale-factor: calc(var(--total-scale-factor) * var(--min-font-size));
  --min-font-size-inv: calc(1 / var(--min-font-size));
}

.book-preview .textLayer :is(span, br) {
  color: transparent;
  position: absolute;
  white-space: pre;
  cursor: text;
  transform-origin: 0% 0%;
  user-select: text;
  -webkit-user-select: text;
}

.book-preview .textLayer > :not(.markedContent),
.book-preview .textLayer .markedContent span:not(.markedContent) {
  z-index: 1;
  --font-height: 0;
  font-size: calc(var(--text-scale-factor) * var(--font-height));
  --scale-x: 1;
  --rotate: 0deg;
  transform: rotate(var(--rotate)) scaleX(var(--scale-x))
    scale(var(--min-font-size-inv));
}

.book-preview .textLayer .markedContent {
  display: contents;
}

.book-preview .textLayer ::selection {
  background: color-mix(in oklab, var(--primary) 35%, transparent);
}

/* In-document search marks. Amber rather than the theme accent so hits are
   visibly distinct from a user's own text selection. */
.book-preview .textLayer span[data-pdf-search-hit] {
  background: hsl(48 96% 62% / 0.42);
  border-radius: 2px;
}

@media (prefers-contrast: more) {
  .book-preview .textLayer span[data-pdf-search-hit] {
    background: hsl(48 96% 62% / 0.7);
  }
}

/* In-document link annotations sit above the text layer (pdf.js puts its
   annotationLayer there too). Invisible at rest like a real PDF; hover and
   keyboard focus get a quiet affordance so links are discoverable. The parent
   layer is pointer-events:none, so each rect re-enables hit-testing. */
.book-preview [data-book-preview-link] {
  pointer-events: auto;
  background: transparent;
}
.book-preview [data-book-preview-link]:hover,
.book-preview [data-book-preview-link]:focus-visible {
  background: color-mix(in oklab, var(--primary) 18%, transparent);
  outline: 1px solid color-mix(in oklab, var(--primary) 45%, transparent);
}

/* Read-aloud speaking indicator — three staggered bars. Frozen under
   prefers-reduced-motion (the icon still communicates state). */
@keyframes book-preview-speaking {
  0%,
  100% {
    transform: scaleY(0.35);
  }
  50% {
    transform: scaleY(1);
  }
}

.book-preview .bp-speaking-bar {
  height: 11px;
  transform-origin: bottom;
  animation: book-preview-speaking 0.9s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .book-preview .bp-speaking-bar {
    animation: none;
  }
}

