'use client'

import { useCallback, useEffect, useRef } from 'react'
import {
  BOOK_PREVIEW_BOUNDARY_RESISTANCE,
  BOOK_PREVIEW_COMMIT_RATIO,
  BOOK_PREVIEW_EASE_OUT,
  BOOK_PREVIEW_GESTURE_INTENT_PX,
  BOOK_PREVIEW_SETTLE_MS,
  BOOK_PREVIEW_VELOCITY_COMMIT,
  BOOK_PREVIEW_MOMENTUM_MS,
} from '../motion'

type GestureOptions = {
  enabled: boolean
  reducedMotion: boolean
  canGoPrev: boolean
  canGoNext: boolean
  onCommitPrev: () => void
  onCommitNext: () => void
}

type GestureState = {
  pointerId: number | null
  startX: number
  startY: number
  lastX: number
  lastT: number
  velocity: number
  tracking: boolean
  offset: number
  width: number
}

function rubberband(distance: number, limit: number): number {
  if (limit <= 0) return 0
  const resisted = distance * BOOK_PREVIEW_BOUNDARY_RESISTANCE
  return Math.max(-limit, Math.min(limit, resisted))
}

function readOffsetX(node: HTMLElement): number {
  const transform = getComputedStyle(node).transform
  if (!transform || transform === 'none') return 0
  try {
    return new DOMMatrixReadOnly(transform).m41
  } catch {
    return 0
  }
}

export function usePageGesture(options: GestureOptions) {
  const surfaceRef = useRef<HTMLDivElement | null>(null)
  const settleTimerRef = useRef<number | null>(null)
  const settleListenerRef = useRef<{
    node: HTMLElement
    listener: (event: TransitionEvent) => void
  } | null>(null)
  const optionsRef = useRef(options)
  useEffect(() => {
    optionsRef.current = options
  })
  const stateRef = useRef<GestureState>({
    pointerId: null,
    startX: 0,
    startY: 0,
    lastX: 0,
    lastT: 0,
    velocity: 0,
    tracking: false,
    offset: 0,
    width: 1,
  })

  const clearSettle = useCallback(() => {
    if (settleTimerRef.current !== null) {
      window.clearTimeout(settleTimerRef.current)
      settleTimerRef.current = null
    }
    // A cancelled settle must also drop its transitionend listener, or a
    // later unrelated transition can fire the stale commit.
    const pending = settleListenerRef.current
    if (pending) {
      pending.node.removeEventListener('transitionend', pending.listener)
      settleListenerRef.current = null
    }
  }, [])

  const setOffset = useCallback((value: number, immediate = false) => {
    const node = surfaceRef.current
    if (!node) return
    node.style.transform = `translate3d(${value}px, 0, 0)`
    node.style.transition = immediate
      ? 'none'
      : `transform ${BOOK_PREVIEW_SETTLE_MS}ms ${BOOK_PREVIEW_EASE_OUT}`
    stateRef.current.offset = value
  }, [])

  const settleTo = useCallback(
    (target: number, onSettled?: () => void) => {
      clearSettle()
      const node = surfaceRef.current
      if (!node) {
        onSettled?.()
        return
      }
      if (optionsRef.current.reducedMotion) {
        setOffset(0, true)
        onSettled?.()
        return
      }
      setOffset(target, false)

      let finished = false
      const finish = () => {
        if (finished) return
        finished = true
        settleListenerRef.current = null
        node.removeEventListener('transitionend', onTransitionEnd)
        clearSettle()
        if (target !== 0) {
          // Commit the page change first, then re-enter from the opposite
          // edge so the incoming spread keeps traveling in the flick's
          // direction instead of snapping back to center.
          onSettled?.()
          setOffset(-target, true)
          requestAnimationFrame(() => setOffset(0, false))
          return
        }
        onSettled?.()
      }
      const onTransitionEnd = (event: TransitionEvent) => {
        if (event.propertyName === 'transform' && event.target === node)
          finish()
      }
      node.addEventListener('transitionend', onTransitionEnd)
      settleListenerRef.current = { node, listener: onTransitionEnd }
      // transitionend is not guaranteed (hidden tab, detached node, display
      // changes), so the commit must not depend on it alone.
      settleTimerRef.current = window.setTimeout(
        finish,
        BOOK_PREVIEW_SETTLE_MS + 80,
      )
    },
    [clearSettle, setOffset],
  )

  useEffect(() => {
    const node = surfaceRef.current
    if (!node || !options.enabled) return

    const onPointerDown = (event: PointerEvent) => {
      // A second finger must not hijack an in-flight drag.
      if (event.button !== 0 || stateRef.current.pointerId !== null) return
      clearSettle()
      // If a settle transition is still in flight, pick up the live painted
      // position so the page stays glued to the finger instead of jumping.
      const liveOffset = readOffsetX(node)
      if (Math.abs(liveOffset) > 0.5) setOffset(liveOffset, true)
      const bounds = node.getBoundingClientRect()
      stateRef.current = {
        pointerId: event.pointerId,
        startX: event.clientX - liveOffset,
        startY: event.clientY,
        lastX: event.clientX,
        lastT: event.timeStamp,
        velocity: 0,
        tracking: Math.abs(liveOffset) > 0.5,
        offset: liveOffset,
        width: bounds.width,
      }
      node.setPointerCapture(event.pointerId)
    }

    const onPointerMove = (event: PointerEvent) => {
      const state = stateRef.current
      const current = optionsRef.current
      if (state.pointerId !== event.pointerId) return
      const dx = event.clientX - state.startX
      const dy = event.clientY - state.startY
      if (!state.tracking) {
        if (Math.abs(dx) < BOOK_PREVIEW_GESTURE_INTENT_PX) return
        if (Math.abs(dy) > Math.abs(dx)) {
          state.pointerId = null
          return
        }
        state.tracking = true
      }
      event.preventDefault()
      const dt = Math.max(1, event.timeStamp - state.lastT)
      const instant = (event.clientX - state.lastX) / dt
      state.velocity = state.velocity * 0.55 + instant * 0.45
      state.lastX = event.clientX
      state.lastT = event.timeStamp

      let next = dx
      if (dx > 0 && !current.canGoPrev) next = rubberband(dx, state.width * 0.4)
      if (dx < 0 && !current.canGoNext) next = rubberband(dx, state.width * 0.4)
      setOffset(next, true)
    }

    const finish = (event: PointerEvent) => {
      const state = stateRef.current
      const current = optionsRef.current
      if (state.pointerId !== event.pointerId) return
      if (node.hasPointerCapture(event.pointerId)) {
        node.releasePointerCapture(event.pointerId)
      }
      state.pointerId = null
      if (!state.tracking) {
        setOffset(0, true)
        return
      }

      // Project where the flick is heading so the page commits to where the
      // gesture was going, not where the finger happened to stop.
      const projected = state.offset + state.velocity * BOOK_PREVIEW_MOMENTUM_MS
      const shouldNext =
        current.canGoNext &&
        (projected < -state.width * BOOK_PREVIEW_COMMIT_RATIO ||
          state.velocity < -BOOK_PREVIEW_VELOCITY_COMMIT)
      const shouldPrev =
        current.canGoPrev &&
        (projected > state.width * BOOK_PREVIEW_COMMIT_RATIO ||
          state.velocity > BOOK_PREVIEW_VELOCITY_COMMIT)

      if (shouldNext) {
        settleTo(-state.width, current.onCommitNext)
        return
      }
      if (shouldPrev) {
        settleTo(state.width, current.onCommitPrev)
        return
      }
      settleTo(0)
    }

    node.addEventListener('pointerdown', onPointerDown)
    node.addEventListener('pointermove', onPointerMove)
    node.addEventListener('pointerup', finish)
    node.addEventListener('pointercancel', finish)

    return () => {
      node.removeEventListener('pointerdown', onPointerDown)
      node.removeEventListener('pointermove', onPointerMove)
      node.removeEventListener('pointerup', finish)
      node.removeEventListener('pointercancel', finish)
      clearSettle()
    }
  }, [options.enabled, clearSettle, setOffset, settleTo])

  useEffect(() => () => clearSettle(), [clearSettle])

  return { surfaceRef, reset: () => setOffset(0, true) }
}

'use client'

import { useLayoutEffect, useRef, useState } from 'react'
import { BOOK_PREVIEW_UI_MS } from '../motion'

type ArrivalPhase = 'entering' | 'settled' | 'instant'

type PageArrival = {
  'data-book-preview-page': true
  'data-enter-dir': 'next' | 'prev'
  'data-mounted'?: true
  'data-instant'?: true
}

/**
 * Entry-animation state for a page element that remounts on every turn.
 *
 * Spread the result onto the element. When turns arrive faster than the
 * animation lasts, the entrance is skipped rather than restarted: holding an
 * arrow key would otherwise replay the same 220ms slide several times a
 * second, which reads as flicker rather than movement. The first paint is
 * "settled" too, so opening the reader does not animate.
 *
 * Timing lives in the layout effect, not in render -- reading a clock during
 * render is impure and makes the result depend on when React happens to
 * re-render.
 */
export function usePageArrival(
  pageIndex: number,
  instant = false,
): PageArrival {
  const [prevIndex, setPrevIndex] = useState(pageIndex)
  const [enterDir, setEnterDir] = useState<'next' | 'prev'>('next')
  const [phase, setPhase] = useState<ArrivalPhase>('settled')
  const lastTurnRef = useRef(0)

  if (prevIndex !== pageIndex) {
    setPrevIndex(pageIndex)
    setEnterDir(pageIndex > prevIndex ? 'next' : 'prev')
    setPhase('entering')
  }

  useLayoutEffect(() => {
    if (phase !== 'entering') return
    const now = performance.now()
    const rapid = now - lastTurnRef.current < BOOK_PREVIEW_UI_MS
    lastTurnRef.current = now
    if (rapid) {
      setPhase('instant')
      return
    }
    // Hold the entry state for one frame so the transition has a start value.
    const frame = requestAnimationFrame(() => setPhase('settled'))
    return () => cancelAnimationFrame(frame)
  }, [phase, pageIndex])

  return {
    'data-book-preview-page': true,
    'data-enter-dir': enterDir,
    ...(phase === 'entering' && !instant
      ? {}
      : { 'data-mounted': true as const }),
    ...(phase === 'instant' || instant
      ? { 'data-instant': true as const }
      : {}),
  }
}

'use client'

import { useCallback, useEffect, useRef } from 'react'

export function useStableHandler<Args extends unknown[], Result>(
  handler: (...args: Args) => Result,
): (...args: Args) => Result {
  const handlerRef = useRef(handler)
  useEffect(() => {
    handlerRef.current = handler
  })
  return useCallback((...args: Args) => handlerRef.current(...args), [])
}

'use client'

import { useEffect } from 'react'
import { BookPreviewPageView } from '../book-preview-page'
import { DEFAULT_CAPABILITIES } from '../capabilities'
import { usePageArrival } from '../hooks/use-page-arrival'
import { usePageGesture } from '../hooks/use-page-gesture'
import { useStableHandler } from '../hooks/use-stable-handler'
import { playPageTurnSound } from '../audio'
import type { BookPreviewEngineProps } from '../types'

export default function PageEngine({
  source,
  pageIndex,
  appearance,
  soundEnabled,
  reducedMotion,
  navigationBehavior,
  onPageChange,
  onReady,
  onError,
}: BookPreviewEngineProps) {
  const pages = source.pages
  const currentPage = pages[pageIndex]
  const facingPage = pages[pageIndex + 1]
  const canGoPrev = pageIndex > 0
  const reportReady = useStableHandler(onReady)
  const reportError = useStableHandler(onError)

  // Forward turns arrive from the right edge, backward turns from the left.
  const arrival = usePageArrival(
    pageIndex,
    reducedMotion || navigationBehavior === 'instant',
  )

  useEffect(() => {
    if (pages.length === 0) {
      reportError({ kind: 'empty', message: 'This reader needs page data.' })
      return
    }
    reportReady({
      totalPages: pages.length,
      capabilities: {
        ...DEFAULT_CAPABILITIES,
        spreads: true,
        download: Boolean(source.downloadUrl),
      },
    })
  }, [pages.length, reportError, reportReady, source.downloadUrl])

  const { surfaceRef } = usePageGesture({
    enabled: true,
    reducedMotion,
    canGoPrev,
    canGoNext: pageIndex < pages.length - 1,
    onCommitPrev: () => {
      if (soundEnabled) playPageTurnSound()
      onPageChange(Math.max(0, pageIndex - 1), 'instant')
    },
    onCommitNext: () => {
      if (soundEnabled) playPageTurnSound()
      onPageChange(Math.min(pages.length - 1, pageIndex + 1), 'instant')
    },
  })

  if (pages.length === 0 || !currentPage) return null

  return (
    <div className="flex h-full w-full items-center justify-center p-4">
      <div
        ref={surfaceRef}
        data-book-preview-slide
        className="bg-background flex max-w-full overflow-hidden rounded-md border shadow-lg select-none"
        style={{ touchAction: 'pan-y' }}
      >
        <div key={pageIndex} {...arrival} className="flex">
          <div
            data-bp-annotatable
            data-page-index={pageIndex}
            className="h-[min(22rem,68svh)] w-[min(14rem,86cqw)] sm:h-[min(32rem,72svh)] sm:w-[20rem] sm:border-r lg:h-[min(40rem,76svh)] lg:w-[25rem] xl:h-[min(46rem,80svh)] xl:w-[28rem]"
          >
            <BookPreviewPageView
              page={currentPage}
              appearance={appearance}
              isLeftPage
            />
          </div>
          <div
            data-bp-annotatable
            data-page-index={pageIndex + 1}
            className="hidden h-[22rem] w-[14rem] sm:block sm:h-[min(32rem,72svh)] sm:w-[20rem] lg:h-[min(40rem,76svh)] lg:w-[25rem] xl:h-[min(46rem,80svh)] xl:w-[28rem]"
          >
            {facingPage ? (
              <BookPreviewPageView page={facingPage} appearance={appearance} />
            ) : (
              <div className="bg-muted text-muted-foreground flex h-full items-center justify-center px-6 text-center text-xs">
                Endpaper
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

/**
 * Shareable reader state in the query string. A link someone copies should
 * open on the same page, in the same mode, layout, and paper — and a refresh
 * must never throw any of that away.
 *
 * The pure helpers below are what the shell and engines share; they never
 * touch `window`, so bun tests them directly. The two browser wrappers at the
 * bottom are the only place history is written, always with replaceState —
 * turning pages must never spam the back stack.
 */

export type BookPreviewUrlKeys = {
  /** One-based page number, e.g. `?page=12`. */
  page?: string
  /** Reader mode id, e.g. `?mode=premier`. */
  mode?: string
  /** Paper appearance, e.g. `?theme=sepia`. */
  appearance?: string
  /** Engine-level layout (the premier reader's book/single/spread/scroll/text). */
  view?: string
}

export const DEFAULT_URL_KEYS: Required<BookPreviewUrlKeys> = {
  page: 'page',
  mode: 'mode',
  appearance: 'theme',
  view: 'view',
}

/**
 * `urlState` accepts `true` for the default keys, or an object that renames
 * or opts into individual keys. The legacy `pageParam` prop still works and
 * wins for the page key.
 */
export function resolveUrlKeys(
  urlState: boolean | BookPreviewUrlKeys | undefined,
  pageParam: string | undefined,
): BookPreviewUrlKeys {
  const keys: BookPreviewUrlKeys =
    urlState === true
      ? { ...DEFAULT_URL_KEYS }
      : urlState
        ? { ...urlState }
        : {}
  if (pageParam) keys.page = pageParam
  return keys
}

/** Reads one value, returning null for a missing or blank key. */
export function readParam(search: string, key: string | undefined) {
  if (!key) return null
  const value = new URLSearchParams(search).get(key)
  return value === null || value.trim() === '' ? null : value
}

/** Parses a one-based page param into a zero-based index, or null. */
export function parsePageParam(raw: string | null): number | null {
  if (raw === null) return null
  const parsed = Number.parseInt(raw, 10)
  return Number.isFinite(parsed) && parsed > 0 ? parsed - 1 : null
}

/** Narrows a param to one of the allowed values. */
export function pickAllowed<T extends string>(
  raw: string | null,
  allowed: readonly T[],
): T | null {
  return raw !== null && (allowed as readonly string[]).includes(raw)
    ? (raw as T)
    : null
}

/**
 * Applies a patch to a query string and returns the new one — or null when
 * nothing changed, so callers can skip a redundant replaceState. A null value
 * removes the key; undefined keys are ignored.
 */
export function patchSearch(
  search: string,
  patch: Record<string, string | null | undefined>,
): string | null {
  const params = new URLSearchParams(search)
  let changed = false
  for (const [key, value] of Object.entries(patch)) {
    if (!key || value === undefined) continue
    const current = params.get(key)
    if (value === null) {
      if (current !== null) {
        params.delete(key)
        changed = true
      }
      continue
    }
    if (current !== value) {
      params.set(key, value)
      changed = true
    }
  }
  if (!changed) return null
  const next = params.toString()
  return next ? `?${next}` : ''
}

export function readUrlParam(key: string | undefined): string | null {
  if (typeof window === 'undefined') return null
  try {
    return readParam(window.location.search, key)
  } catch {
    return null
  }
}

export function writeUrlParams(
  patch: Record<string, string | null | undefined>,
): void {
  if (typeof window === 'undefined') return
  try {
    const next = patchSearch(window.location.search, patch)
    if (next === null) return
    const url = `${window.location.pathname}${next}${window.location.hash}`
    // Keep whatever state the router stored — Next's app router keeps its
    // tree in history.state, and a null here would drop it.
    window.history.replaceState(window.history.state, '', url)
  } catch {
    // history may be unavailable (sandboxed iframe).
  }
}

/**
 * Reader typography — the "Aa" settings. Pure data and CSS-variable mapping,
 * no DOM, so bun can test it. Text pages and the premier text view read these
 * variables; rasterized PDF pages are pictures of type and are unaffected.
 */

export const TYPOGRAPHY_FONTS = ['serif', 'sans', 'readable', 'mono'] as const
export type TypographyFont = (typeof TYPOGRAPHY_FONTS)[number]

export const TYPOGRAPHY_SPACINGS = ['compact', 'normal', 'relaxed'] as const
export type TypographySpacing = (typeof TYPOGRAPHY_SPACINGS)[number]

export const TYPOGRAPHY_WIDTHS = ['narrow', 'normal', 'wide'] as const
export type TypographyWidth = (typeof TYPOGRAPHY_WIDTHS)[number]

export type BookPreviewTypography = {
  /** Multiplier over the page's own type size, 0.8 – 1.6. */
  scale: number
  font: TypographyFont
  spacing: TypographySpacing
  width: TypographyWidth
  justify: boolean
}

export const DEFAULT_TYPOGRAPHY: BookPreviewTypography = {
  scale: 1,
  font: 'serif',
  spacing: 'normal',
  width: 'normal',
  justify: false,
}

export const TYPOGRAPHY_SCALE_MIN = 0.8
export const TYPOGRAPHY_SCALE_MAX = 1.6
export const TYPOGRAPHY_SCALE_STEP = 0.1

export function stepTypographyScale(scale: number, direction: 1 | -1) {
  const next = Math.round((scale + direction * TYPOGRAPHY_SCALE_STEP) * 10) / 10
  return Math.min(TYPOGRAPHY_SCALE_MAX, Math.max(TYPOGRAPHY_SCALE_MIN, next))
}

const FONT_STACKS: Record<TypographyFont, string> = {
  serif:
    'ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif',
  sans: 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
  // Wide apertures and distinct letterforms (b/d, I/l/1) — the traits that
  // help dyslexic and low-vision readers — from fonts already on the device.
  readable:
    '"Atkinson Hyperlegible", "Atkinson Hyperlegible Next", Verdana, Tahoma, sans-serif',
  mono: 'ui-monospace, "SF Mono", Menlo, Consolas, monospace',
}

const LINE_HEIGHTS: Record<TypographySpacing, number> = {
  compact: 1.45,
  normal: 1.7,
  relaxed: 1.95,
}

/** Characters per line, the measure typographers actually tune by. */
const MEASURES: Record<TypographyWidth, string> = {
  narrow: '32rem',
  normal: '40rem',
  wide: '52rem',
}

export function typographyVariables(
  typography: BookPreviewTypography,
): Record<string, string> {
  return {
    '--bp-type-scale': String(typography.scale),
    '--bp-type-family': FONT_STACKS[typography.font],
    '--bp-type-leading': String(LINE_HEIGHTS[typography.spacing]),
    '--bp-type-measure': MEASURES[typography.width],
    '--bp-type-align': typography.justify ? 'justify' : 'start',
    '--bp-type-tracking': typography.font === 'readable' ? '0.02em' : 'normal',
  }
}

/** Validates an untrusted stored value field by field, keeping the defaults
    for anything malformed. */
export function sanitizeTypography(raw: unknown): BookPreviewTypography {
  if (!raw || typeof raw !== 'object') return { ...DEFAULT_TYPOGRAPHY }
  const value = raw as Record<string, unknown>
  const scale =
    typeof value.scale === 'number' && Number.isFinite(value.scale)
      ? Math.min(
          TYPOGRAPHY_SCALE_MAX,
          Math.max(TYPOGRAPHY_SCALE_MIN, value.scale),
        )
      : DEFAULT_TYPOGRAPHY.scale
  const pick = <T extends string>(input: unknown, allowed: readonly T[]) =>
    typeof input === 'string' && (allowed as readonly string[]).includes(input)
      ? (input as T)
      : null
  return {
    scale,
    font: pick(value.font, TYPOGRAPHY_FONTS) ?? DEFAULT_TYPOGRAPHY.font,
    spacing:
      pick(value.spacing, TYPOGRAPHY_SPACINGS) ?? DEFAULT_TYPOGRAPHY.spacing,
    width: pick(value.width, TYPOGRAPHY_WIDTHS) ?? DEFAULT_TYPOGRAPHY.width,
    justify:
      typeof value.justify === 'boolean'
        ? value.justify
        : DEFAULT_TYPOGRAPHY.justify,
  }
}

/**
 * Highlights, notes, and bookmarks — the pure half. No DOM here, so bun tests
 * it directly; the browser half (text indexing, ranges, painting) lives in
 * annotation-dom.ts.
 *
 * Anchoring follows the W3C Web Annotation TextQuoteSelector: a highlight
 * remembers the exact words plus a little context either side, never DOM
 * positions. The PDF text layer is rebuilt on every zoom and differs between
 * views, so node offsets would rot within seconds; a quote survives zoom,
 * view switches, reloads, and devices.
 */

import { INK_COLORS, type BookPreviewInkColor } from './ink'

export const HIGHLIGHT_COLORS = ['yellow', 'green', 'blue', 'pink'] as const
export type BookPreviewHighlightColor = (typeof HIGHLIGHT_COLORS)[number]

export type BookPreviewTextQuote = {
  exact: string
  prefix: string
  suffix: string
}

type AnnotationBase = {
  id: string
  /** Zero-based page the annotation belongs to. */
  pageIndex: number
  /** Epoch milliseconds — lets a sync backend resolve conflicts
      last-write-wins without inventing its own clock. */
  createdAt: number
  updatedAt: number
}

export type BookPreviewHighlight = AnnotationBase & {
  kind: 'highlight'
  quote: BookPreviewTextQuote
  color: BookPreviewHighlightColor
  note?: string
}

export type BookPreviewBookmark = AnnotationBase & {
  kind: 'bookmark'
  label?: string
}

/** One freehand stroke. Points are page-relative (0–1) and flattened
    [x0, y0, x1, y1, …]; width is a fraction of the page width. */
export type BookPreviewInk = AnnotationBase & {
  kind: 'ink'
  tool: 'pen' | 'marker'
  color: BookPreviewInkColor
  width: number
  points: number[]
}

export type BookPreviewAnnotation =
  | BookPreviewHighlight
  | BookPreviewBookmark
  | BookPreviewInk

export const QUOTE_CONTEXT_CHARS = 32

let idCounter = 0
export function createAnnotationId(): string {
  idCounter += 1
  const random =
    typeof crypto !== 'undefined' && 'randomUUID' in crypto
      ? crypto.randomUUID().slice(0, 8)
      : Math.random().toString(36).slice(2, 10)
  return `ann_${Date.now().toString(36)}_${random}${idCounter}`
}

export function createHighlight(input: {
  pageIndex: number
  quote: BookPreviewTextQuote
  color: BookPreviewHighlightColor
  note?: string
}): BookPreviewHighlight {
  const now = Date.now()
  return {
    id: createAnnotationId(),
    kind: 'highlight',
    createdAt: now,
    updatedAt: now,
    ...input,
  }
}

/** Applies an edit and stamps `updatedAt` — the field sync merges on. */
export function editAnnotation<T extends BookPreviewAnnotation>(
  item: T,
  patch: Partial<Omit<T, 'id' | 'kind' | 'createdAt'>>,
): T {
  return { ...item, ...patch, updatedAt: Date.now() }
}

/** Collapses runs of whitespace — text layers and page markup disagree on
    spacing, and a quote must match either way. */
export function normalizeQuoteText(text: string): string {
  return text.replace(/\s+/g, ' ').trim()
}

/** Builds a quote selector for [start, end) of a page's text. */
export function createTextQuote(
  text: string,
  start: number,
  end: number,
  context = QUOTE_CONTEXT_CHARS,
): BookPreviewTextQuote {
  const from = Math.max(0, Math.min(start, end))
  const to = Math.min(text.length, Math.max(start, end))
  return {
    exact: text.slice(from, to),
    prefix: text.slice(Math.max(0, from - context), from),
    suffix: text.slice(to, to + context),
  }
}

function commonSuffixLength(a: string, b: string): number {
  let count = 0
  while (
    count < a.length &&
    count < b.length &&
    a[a.length - 1 - count] === b[b.length - 1 - count]
  ) {
    count += 1
  }
  return count
}

function commonPrefixLength(a: string, b: string): number {
  let count = 0
  while (count < a.length && count < b.length && a[count] === b[count]) {
    count += 1
  }
  return count
}

/** Strips all whitespace and keeps, for each kept character, its offset in
    the original string. Text layers, page markup, and extracted text disagree
    about spaces between runs ("hello world" vs "helloworld"), so matching
    happens on the compacted form and maps back. */
export function compactWithMap(text: string): { text: string; map: number[] } {
  const map: number[] = []
  let out = ''
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index]
    if (/\s/.test(char)) continue
    out += char
    map.push(index)
  }
  return { text: out, map }
}

const compact = (text: string) => text.replace(/\s+/g, '')

/**
 * Finds a quote in a page's text and returns its [start, end) offsets into
 * the original text, or null. Matching ignores whitespace, so a quote taken
 * in one view (the PDF text layer) still lands in another (the text view).
 * When the words occur more than once (a repeated phrase, a running header),
 * the surrounding context picks the right occurrence.
 */
export function locateTextQuote(
  text: string,
  quote: BookPreviewTextQuote,
): { start: number; end: number } | null {
  const exact = compact(quote.exact)
  if (!exact) return null
  const haystack = compactWithMap(text)
  const prefix = compact(quote.prefix)
  const suffix = compact(quote.suffix)
  const hits: number[] = []
  let from = haystack.text.indexOf(exact)
  while (from !== -1) {
    hits.push(from)
    from = haystack.text.indexOf(exact, from + 1)
  }
  if (hits.length === 0) return null
  let best = hits[0]
  if (hits.length > 1) {
    let bestScore = -1
    for (const hit of hits) {
      const before = haystack.text.slice(Math.max(0, hit - prefix.length), hit)
      const after = haystack.text.slice(
        hit + exact.length,
        hit + exact.length + suffix.length,
      )
      const score =
        commonSuffixLength(before, prefix) + commonPrefixLength(after, suffix)
      if (score > bestScore) {
        best = hit
        bestScore = score
      }
    }
  }
  const start = haystack.map[best]
  const end = haystack.map[best + exact.length - 1] + 1
  return { start, end }
}

/** Page order, then creation order — the order a reader meets them. */
export function sortAnnotations<T extends BookPreviewAnnotation>(
  list: readonly T[],
): T[] {
  return [...list].sort(
    (a, b) => a.pageIndex - b.pageIndex || a.createdAt - b.createdAt,
  )
}

export function upsertAnnotation(
  list: readonly BookPreviewAnnotation[],
  next: BookPreviewAnnotation,
): BookPreviewAnnotation[] {
  const index = list.findIndex((item) => item.id === next.id)
  if (index === -1) return [...list, next]
  const copy = [...list]
  copy[index] = next
  return copy
}

export function removeAnnotation(
  list: readonly BookPreviewAnnotation[],
  id: string,
): BookPreviewAnnotation[] {
  return list.filter((item) => item.id !== id)
}

export function findBookmark(
  list: readonly BookPreviewAnnotation[],
  pageIndex: number,
): BookPreviewBookmark | undefined {
  return list.find(
    (item): item is BookPreviewBookmark =>
      item.kind === 'bookmark' && item.pageIndex === pageIndex,
  )
}

export function toggleBookmark(
  list: readonly BookPreviewAnnotation[],
  pageIndex: number,
  now = Date.now(),
): BookPreviewAnnotation[] {
  const existing = findBookmark(list, pageIndex)
  if (existing) return removeAnnotation(list, existing.id)
  return [
    ...list,
    {
      id: createAnnotationId(),
      kind: 'bookmark',
      pageIndex,
      createdAt: now,
      updatedAt: now,
    },
  ]
}

/** Highlights whose [start, end) on a page contains `offset`. Newest first,
    so a tap on overlapping highlights edits the one made last. */
export function highlightsAt(
  located: readonly { id: string; start: number; end: number }[],
  offset: number,
): string[] {
  return located
    .filter((item) => offset >= item.start && offset < item.end)
    .map((item) => item.id)
    .reverse()
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object'

const isFiniteNumber = (value: unknown): value is number =>
  typeof value === 'number' && Number.isFinite(value)

/** Drops anything malformed from stored or synced data rather than letting
    one bad record break the whole notebook. */
export function sanitizeAnnotations(raw: unknown): BookPreviewAnnotation[] {
  if (!Array.isArray(raw)) return []
  const out: BookPreviewAnnotation[] = []
  for (const item of raw) {
    if (!isRecord(item)) continue
    if (typeof item.id !== 'string' || !item.id) continue
    if (!isFiniteNumber(item.pageIndex) || item.pageIndex < 0) continue
    const createdAt = isFiniteNumber(item.createdAt) ? item.createdAt : 0
    const updatedAt = isFiniteNumber(item.updatedAt)
      ? item.updatedAt
      : createdAt
    const base = {
      id: item.id,
      pageIndex: Math.trunc(item.pageIndex),
      createdAt,
      updatedAt,
    }
    if (item.kind === 'bookmark') {
      out.push({
        ...base,
        kind: 'bookmark',
        ...(typeof item.label === 'string' ? { label: item.label } : {}),
      })
      continue
    }
    if (item.kind === 'ink') {
      const points = Array.isArray(item.points)
        ? item.points.filter(isFiniteNumber)
        : []
      // An odd count means a truncated pair — drop the dangling coordinate.
      const even = points.length % 2 === 0 ? points : points.slice(0, -1)
      if (even.length < 2) continue
      out.push({
        ...base,
        kind: 'ink',
        tool: item.tool === 'marker' ? 'marker' : 'pen',
        color: (INK_COLORS as readonly string[]).includes(item.color as string)
          ? (item.color as BookPreviewInkColor)
          : 'ink',
        width:
          isFiniteNumber(item.width) && item.width > 0 && item.width < 0.2
            ? item.width
            : 0.0035,
        points: even.map((value) => Math.min(1, Math.max(0, value))),
      })
      continue
    }
    if (item.kind !== 'highlight' || !isRecord(item.quote)) continue
    const quote = item.quote
    if (typeof quote.exact !== 'string' || !quote.exact) continue
    const color = (HIGHLIGHT_COLORS as readonly string[]).includes(
      item.color as string,
    )
      ? (item.color as BookPreviewHighlightColor)
      : 'yellow'
    out.push({
      ...base,
      kind: 'highlight',
      color,
      quote: {
        exact: quote.exact,
        prefix: typeof quote.prefix === 'string' ? quote.prefix : '',
        suffix: typeof quote.suffix === 'string' ? quote.suffix : '',
      },
      ...(typeof item.note === 'string' && item.note
        ? { note: item.note }
        : {}),
    })
  }
  return out
}

export function annotationsStorageKey(sourceKey: string): string {
  return `book-preview:annotations:${sourceKey}`
}

/** A reader's notebook as Markdown — quotes as blockquotes, notes beneath,
    bookmarks as a list — ready for Obsidian, Notion, or an email. */
export function annotationsToMarkdown(
  list: readonly BookPreviewAnnotation[],
  meta: { title?: string; author?: string } = {},
): string {
  const lines: string[] = []
  lines.push(`# ${meta.title ?? 'Reading notes'}`)
  if (meta.author) lines.push('', `_${meta.author}_`)
  const sorted = sortAnnotations(list)
  const bookmarks = sorted.filter((item) => item.kind === 'bookmark')
  const highlights = sorted.filter(
    (item): item is BookPreviewHighlight => item.kind === 'highlight',
  )
  if (bookmarks.length > 0) {
    lines.push('', '## Bookmarks', '')
    for (const mark of bookmarks) {
      lines.push(
        `- Page ${mark.pageIndex + 1}${mark.label ? ` — ${mark.label}` : ''}`,
      )
    }
  }
  if (highlights.length > 0) {
    lines.push('', '## Highlights')
    for (const item of highlights) {
      lines.push(
        '',
        `**Page ${item.pageIndex + 1}** · ${item.color}`,
        '',
        `> ${normalizeQuoteText(item.quote.exact)}`,
      )
      if (item.note) lines.push('', item.note.trim())
    }
  }
  const inkPages = new Map<number, number>()
  for (const item of sorted) {
    if (item.kind === 'ink') {
      inkPages.set(item.pageIndex, (inkPages.get(item.pageIndex) ?? 0) + 1)
    }
  }
  if (inkPages.size > 0) {
    lines.push('', '## Drawings', '')
    for (const [page, strokes] of inkPages) {
      lines.push(
        `- Page ${page + 1} — ${strokes} ${strokes === 1 ? 'stroke' : 'strokes'}`,
      )
    }
  }
  if (
    bookmarks.length === 0 &&
    highlights.length === 0 &&
    inkPages.size === 0
  ) {
    lines.push('', '_No highlights or bookmarks yet._')
  }
  return `${lines.join('\n')}\n`
}

/**
 * The browser half of annotations: turning a page's DOM into one searchable
 * string, mapping selections to offsets and offsets back to ranges, and
 * painting highlights with the CSS Custom Highlight API.
 *
 * The Highlight API paints ranges without touching the DOM — no <mark>
 * wrappers splitting pdf.js spans or React-owned text nodes, nothing for a
 * re-render to throw away. Where it is missing, highlights still live in the
 * notebook; they simply are not painted on the page.
 */

import type { BookPreviewHighlightColor } from './annotations'

/** Pages that can carry highlights mark their text root with this attribute
    plus `data-page-index`. Folio labels and other chrome inside a page opt
    out with `data-bp-annotate-skip`. */
export const ANNOTATABLE_SELECTOR = '[data-bp-annotatable]'

export type TextIndex = {
  text: string
  nodes: { node: Text; start: number }[]
}

export function buildTextIndex(container: Element): TextIndex {
  const nodes: TextIndex['nodes'] = []
  let text = ''
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = node.parentElement
      if (!parent || parent.closest('[data-bp-annotate-skip]')) {
        return NodeFilter.FILTER_REJECT
      }
      return node.nodeValue
        ? NodeFilter.FILTER_ACCEPT
        : NodeFilter.FILTER_REJECT
    },
  })
  let current = walker.nextNode()
  while (current) {
    const node = current as Text
    nodes.push({ node, start: text.length })
    text += node.nodeValue ?? ''
    current = walker.nextNode()
  }
  return { text, nodes }
}

/** A DOM boundary point → offset into the index text. Element boundaries
    (a selection that starts "between" spans) resolve to the next text node. */
export function offsetFromPoint(
  index: TextIndex,
  node: Node,
  offset: number,
): number {
  if (node.nodeType === Node.TEXT_NODE) {
    const entry = index.nodes.find((item) => item.node === node)
    if (entry) return entry.start + Math.min(offset, entry.node.length)
  }
  const probe = document.createRange()
  try {
    probe.setStart(node, offset)
  } catch {
    return index.text.length
  }
  for (const entry of index.nodes) {
    // A text node at or after the point is where the selection really begins.
    if (probe.comparePoint(entry.node, 0) >= 0) return entry.start
    if (probe.comparePoint(entry.node, entry.node.length) >= 0) {
      return entry.start + entry.node.length
    }
  }
  return index.text.length
}

export function rangeFromOffsets(
  index: TextIndex,
  start: number,
  end: number,
): Range | null {
  if (end <= start || index.nodes.length === 0) return null
  const locate = (offset: number, preferNext: boolean) => {
    for (let i = 0; i < index.nodes.length; i += 1) {
      const entry = index.nodes[i]
      const nodeEnd = entry.start + entry.node.length
      if (offset < nodeEnd || (!preferNext && offset === nodeEnd)) {
        return { node: entry.node, offset: Math.max(0, offset - entry.start) }
      }
    }
    const last = index.nodes[index.nodes.length - 1]
    return { node: last.node, offset: last.node.length }
  }
  const from = locate(start, true)
  const to = locate(end, false)
  const range = document.createRange()
  try {
    range.setStart(from.node, from.offset)
    range.setEnd(to.node, to.offset)
  } catch {
    return null
  }
  return range
}

export function annotatableFor(node: Node | null): HTMLElement | null {
  const element = node instanceof Element ? node : (node?.parentElement ?? null)
  return (element?.closest(ANNOTATABLE_SELECTOR) as HTMLElement | null) ?? null
}

export function pageIndexOf(container: HTMLElement): number | null {
  const raw = Number.parseInt(container.dataset.pageIndex ?? '', 10)
  return Number.isFinite(raw) && raw >= 0 ? raw : null
}

/** The caret under a point — standard API first, WebKit's fallback second. */
export function caretFromPoint(
  x: number,
  y: number,
): { node: Node; offset: number } | null {
  const doc = document as Document & {
    caretPositionFromPoint?: (
      x: number,
      y: number,
    ) => { offsetNode: Node; offset: number } | null
    caretRangeFromPoint?: (x: number, y: number) => Range | null
  }
  if (typeof doc.caretPositionFromPoint === 'function') {
    const position = doc.caretPositionFromPoint(x, y)
    return position
      ? { node: position.offsetNode, offset: position.offset }
      : null
  }
  if (typeof doc.caretRangeFromPoint === 'function') {
    const range = doc.caretRangeFromPoint(x, y)
    return range
      ? { node: range.startContainer, offset: range.startOffset }
      : null
  }
  return null
}

type HighlightRegistry = {
  set: (name: string, highlight: unknown) => void
  delete: (name: string) => void
}

function highlightApi(): {
  registry: HighlightRegistry
  Highlight: new (...ranges: Range[]) => unknown
} | null {
  if (typeof window === 'undefined') return null
  const registry = (globalThis.CSS as { highlights?: HighlightRegistry })
    ?.highlights
  const Highlight = (
    globalThis as { Highlight?: new (...ranges: Range[]) => unknown }
  ).Highlight
  return registry && Highlight ? { registry, Highlight } : null
}

// Translucent inks so the page — a raster under a transparent text layer, or
// real text — reads through. Injected once per document rather than shipped
// in the stylesheet: build-time CSS parsers do not know ::highlight() yet.
const HIGHLIGHT_STYLES = `
::highlight(bp-hl-yellow) { background-color: rgb(250 204 21 / 0.38); }
::highlight(bp-hl-green) { background-color: rgb(74 222 128 / 0.34); }
::highlight(bp-hl-blue) { background-color: rgb(96 165 250 / 0.34); }
::highlight(bp-hl-pink) { background-color: rgb(244 114 182 / 0.34); }
@media (prefers-contrast: more) {
  ::highlight(bp-hl-yellow), ::highlight(bp-hl-green),
  ::highlight(bp-hl-blue), ::highlight(bp-hl-pink) {
    text-decoration: underline 2px;
  }
}`

function ensureHighlightStyles() {
  if (document.getElementById('bp-highlight-styles')) return
  const style = document.createElement('style')
  style.id = 'bp-highlight-styles'
  style.textContent = HIGHLIGHT_STYLES
  document.head.append(style)
}

export function supportsHighlightPainting(): boolean {
  return highlightApi() !== null
}

export const highlightName = (color: BookPreviewHighlightColor) =>
  `bp-hl-${color}`

// The registry is document-global and names are fixed (CSS must reference
// them), so every reader instance contributes its ranges here and one commit
// merges them — two readers on a page never erase each other.
const layers = new Map<string, Map<BookPreviewHighlightColor, Range[]>>()

function commit(colors: readonly BookPreviewHighlightColor[]) {
  const api = highlightApi()
  if (!api) return
  for (const color of colors) {
    const ranges: Range[] = []
    for (const layer of layers.values())
      ranges.push(...(layer.get(color) ?? []))
    if (ranges.length === 0) api.registry.delete(highlightName(color))
    else api.registry.set(highlightName(color), new api.Highlight(...ranges))
  }
}

export function paintHighlights(
  instance: string,
  byColor: Map<BookPreviewHighlightColor, Range[]>,
  colors: readonly BookPreviewHighlightColor[],
) {
  ensureHighlightStyles()
  layers.set(instance, byColor)
  commit(colors)
}

export function clearHighlights(
  instance: string,
  colors: readonly BookPreviewHighlightColor[],
) {
  layers.delete(instance)
  commit(colors)
}

/**
 * "Ask" — a provider-agnostic hook for putting a model next to the page.
 *
 * The reader never talks to a vendor itself. A host passes an adapter: the
 * on-device one below (Chrome's built-in model — private, free, offline), an
 * OpenAI-compatible endpoint (Ollama or LM Studio on localhost), or its own
 * server route that holds the API key. Every adapter gets the same grounded
 * context — the selection, the page text, the document title — and streams
 * text back.
 */

export type BookPreviewAskRequest = {
  question: string
  /** The passage the reader selected, if the question is about one. */
  selection?: string
  pageIndex: number
  /** Plain text of the current page (and the facing page in spreads). */
  pageText: string
  title?: string
  author?: string
}

export type BookPreviewAiAdapter = {
  /** Shown under the answer, e.g. "On-device · Gemini Nano". */
  label: string
  /** Resolves false when the adapter cannot run here; the Ask tab then
      explains instead of failing mid-question. */
  isAvailable?: () => Promise<boolean> | boolean
  ask: (
    request: BookPreviewAskRequest,
    options: { signal: AbortSignal },
  ) => AsyncIterable<string> | Promise<string>
}

/** Page text past this is trimmed from the prompt — enough for a dense page
    and its facing page, small enough for on-device context windows. */
export const ASK_PAGE_TEXT_LIMIT = 6000

export const ASK_SYSTEM_PROMPT =
  'You are a reading companion inside a book and document reader. Answer ' +
  'using the provided page text first; say plainly when the page does not ' +
  'contain the answer and you are drawing on general knowledge. Be concise ' +
  'and concrete. Quote short phrases from the page when they help.'

export const ASK_QUICK_PROMPTS = [
  { label: 'Explain', question: 'Explain this in simple terms.' },
  { label: 'Summarize page', question: 'Summarize this page in 3 bullets.' },
  { label: 'Define', question: 'Define the key terms here.' },
  {
    label: 'Quiz me',
    question: 'Ask me 3 questions to check I understood this page.',
  },
] as const

export function buildAskPrompt(request: BookPreviewAskRequest): {
  system: string
  user: string
} {
  const page = request.pageText.replace(/\s+/g, ' ').trim()
  const trimmed =
    page.length > ASK_PAGE_TEXT_LIMIT
      ? `${page.slice(0, ASK_PAGE_TEXT_LIMIT)} …`
      : page
  const parts: string[] = []
  const doc = [request.title, request.author && `by ${request.author}`]
    .filter(Boolean)
    .join(' ')
  if (doc) parts.push(`Document: ${doc}`)
  parts.push(
    `Page ${request.pageIndex + 1} text:\n"""\n${trimmed || '(no extractable text on this page)'}\n"""`,
  )
  if (request.selection?.trim()) {
    parts.push(
      `The reader selected this passage:\n"""\n${request.selection.replace(/\s+/g, ' ').trim()}\n"""`,
    )
  }
  parts.push(`Question: ${request.question.trim()}`)
  return { system: ASK_SYSTEM_PROMPT, user: parts.join('\n\n') }
}

/** Collects an adapter's answer as it streams, whether it returned a
    string or an async iterable of chunks. */
export async function streamAnswer(
  result: AsyncIterable<string> | Promise<string>,
  onChunk: (text: string) => void,
): Promise<string> {
  if (typeof (result as Promise<string>).then === 'function') {
    const text = await (result as Promise<string>)
    onChunk(text)
    return text
  }
  let text = ''
  for await (const chunk of result as AsyncIterable<string>) {
    text += chunk
    onChunk(text)
  }
  return text
}

type BuiltInLanguageModel = {
  availability: () => Promise<string>
  create: (options: {
    initialPrompts?: { role: 'system'; content: string }[]
    signal?: AbortSignal
  }) => Promise<{
    promptStreaming: (
      input: string,
      options?: { signal?: AbortSignal },
    ) => AsyncIterable<string>
    destroy: () => void
  }>
}

function builtInModel(): BuiltInLanguageModel | null {
  const candidate = (globalThis as { LanguageModel?: BuiltInLanguageModel })
    .LanguageModel
  return candidate && typeof candidate.create === 'function' ? candidate : null
}

/**
 * The browser's own on-device model (Chrome's Prompt API). Nothing leaves
 * the machine and there is no key to manage. Unavailable in other browsers,
 * so hosts usually chain it before a server adapter.
 */
export function createBuiltInAiAdapter(): BookPreviewAiAdapter {
  return {
    label: 'On-device model',
    async isAvailable() {
      const model = builtInModel()
      if (!model) return false
      try {
        return (await model.availability()) !== 'unavailable'
      } catch {
        return false
      }
    },
    async *ask(request, { signal }) {
      const model = builtInModel()
      if (!model) throw new Error('The on-device model is not available here.')
      const prompt = buildAskPrompt(request)
      const session = await model.create({
        initialPrompts: [{ role: 'system', content: prompt.system }],
        signal,
      })
      try {
        let previous = ''
        for await (const chunk of session.promptStreaming(prompt.user, {
          signal,
        })) {
          // Early Chrome builds streamed the whole answer so far; later ones
          // stream deltas. Accept both.
          if (chunk.startsWith(previous) && previous) {
            yield chunk.slice(previous.length)
            previous = chunk
          } else {
            yield chunk
            previous += chunk
          }
        }
      } finally {
        session.destroy()
      }
    },
  }
}

/** Parses one server-sent-events buffer into complete `data:` payloads and
    the unfinished remainder. */
export function parseSseChunk(buffer: string): {
  events: string[]
  rest: string
} {
  const events: string[] = []
  const blocks = buffer.split(/\r?\n\r?\n/)
  const rest = blocks.pop() ?? ''
  for (const block of blocks) {
    const data = block
      .split(/\r?\n/)
      .filter((line) => line.startsWith('data:'))
      .map((line) => line.slice(5).trimStart())
      .join('\n')
    if (data) events.push(data)
  }
  return { events, rest }
}

/**
 * Any OpenAI-compatible chat endpoint — Ollama (`http://localhost:11434/v1`),
 * LM Studio, vLLM, or a hosted gateway. For local models the page itself can
 * call localhost; for hosted ones, point `baseUrl` at your own proxy so keys
 * never reach the browser.
 */
export function createOpenAICompatibleAdapter(options: {
  baseUrl: string
  model: string
  label?: string
  headers?: Record<string, string>
}): BookPreviewAiAdapter {
  const base = options.baseUrl.replace(/\/$/, '')
  return {
    label: options.label ?? options.model,
    // A quick look at /models tells a running local server from a closed
    // port, so the Ask tab can explain instead of failing mid-question.
    async isAvailable() {
      try {
        const response = await fetch(`${base}/models`, {
          headers: options.headers,
          signal: AbortSignal.timeout(1500),
        })
        return response.ok
      } catch {
        return false
      }
    },
    async *ask(request, { signal }) {
      const prompt = buildAskPrompt(request)
      const response = await fetch(`${base}/chat/completions`, {
        method: 'POST',
        signal,
        headers: { 'content-type': 'application/json', ...options.headers },
        body: JSON.stringify({
          model: options.model,
          stream: true,
          messages: [
            { role: 'system', content: prompt.system },
            { role: 'user', content: prompt.user },
          ],
        }),
      })
      if (!response.ok || !response.body) {
        throw new Error(`The model endpoint answered ${response.status}.`)
      }
      const reader = response.body
        .pipeThrough(new TextDecoderStream())
        .getReader()
      let buffer = ''
      while (true) {
        const { value, done } = await reader.read()
        if (done) break
        buffer += value
        const parsed = parseSseChunk(buffer)
        buffer = parsed.rest
        for (const data of parsed.events) {
          if (data === '[DONE]') return
          try {
            const delta = JSON.parse(data)?.choices?.[0]?.delta?.content
            if (typeof delta === 'string' && delta) yield delta
          } catch {
            // Keep-alive comments and partial frames are not answers.
          }
        }
      }
    },
  }
}

/**
 * Posts the request to the host's own route and streams the plain-text
 * response body. The route holds the provider key and picks the model — the
 * right shape for hosted models (Claude, GPT, Gemini) in production.
 */
export function createFetchAiAdapter(options: {
  url: string
  label?: string
  headers?: Record<string, string>
}): BookPreviewAiAdapter {
  return {
    label: options.label ?? 'Assistant',
    async *ask(request, { signal }) {
      const response = await fetch(options.url, {
        method: 'POST',
        signal,
        headers: { 'content-type': 'application/json', ...options.headers },
        body: JSON.stringify({ ...request, prompt: buildAskPrompt(request) }),
      })
      if (!response.ok || !response.body) {
        throw new Error(`The assistant answered ${response.status}.`)
      }
      const reader = response.body
        .pipeThrough(new TextDecoderStream())
        .getReader()
      while (true) {
        const { value, done } = await reader.read()
        if (done) return
        if (value) yield value
      }
    },
  }
}

/** Tries adapters in order and uses the first that is available — e.g.
    on-device first, then the host's server route. */
export function chainAiAdapters(
  ...adapters: BookPreviewAiAdapter[]
): BookPreviewAiAdapter {
  let chosen: BookPreviewAiAdapter | null | undefined
  const choose = async () => {
    if (chosen !== undefined) return chosen
    for (const adapter of adapters) {
      const ok = adapter.isAvailable ? await adapter.isAvailable() : true
      if (ok) {
        chosen = adapter
        return adapter
      }
    }
    chosen = null
    return null
  }
  return {
    get label() {
      return chosen?.label ?? adapters.map((item) => item.label).join(' / ')
    },
    async isAvailable() {
      return (await choose()) !== null
    },
    async *ask(request, options) {
      const adapter = await choose()
      if (!adapter) throw new Error('No assistant is available here.')
      const result = adapter.ask(request, options)
      if (typeof (result as Promise<string>).then === 'function') {
        yield await (result as Promise<string>)
        return
      }
      yield* result as AsyncIterable<string>
    },
  }
}

'use client'

import { isInteractiveTarget } from '../keyboard'
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type PointerEvent,
  type RefObject,
} from 'react'

/** How long the reader sits still before fullscreen chrome slips away. */
export const CHROME_IDLE_MS = 2600
/** A tap is short and nearly still — anything more is a swipe or a scroll. */
const TAP_MAX_MS = 320
const TAP_MAX_TRAVEL_PX = 10
/** Mouse within this distance of the top or bottom edge wakes the chrome. */
const EDGE_WAKE_PX = 72

/**
 * Fullscreen reading hands the whole screen to the page. Chrome floats over
 * the stage and fades out after a short idle; moving the mouse, nearing an
 * edge, or tapping the middle of the page brings it back — the Apple Books /
 * Kindle contract. Turning pages never wakes it: that is reading, not
 * reaching for controls.
 *
 * The chrome never hides while it is in use: while focus sits inside it or
 * has left the reader (a menu or dialog portalled elsewhere), or while the
 * pointer rests on it.
 */
export function useImmersiveChrome({
  enabled,
  rootRef,
}: {
  enabled: boolean
  rootRef: RefObject<HTMLElement | null>
}) {
  const [hidden, setHidden] = useState(false)
  const timerRef = useRef<number | null>(null)
  const overChromeRef = useRef(false)
  const tapRef = useRef<{ id: number; x: number; y: number; t: number } | null>(
    null,
  )

  const clear = useCallback(() => {
    if (timerRef.current !== null) {
      window.clearTimeout(timerRef.current)
      timerRef.current = null
    }
  }, [])

  const chromeInUse = useCallback(() => {
    const root = rootRef.current
    if (!root) return false
    if (overChromeRef.current) return true
    const active = document.activeElement
    if (!(active instanceof HTMLElement) || active === document.body) {
      return false
    }
    if (!root.contains(active)) return true
    return Boolean(active.closest('[data-book-preview-chrome]'))
  }, [rootRef])

  const scheduleHide = useCallback(() => {
    clear()
    timerRef.current = window.setTimeout(function hideWhenIdle() {
      if (chromeInUse()) {
        timerRef.current = window.setTimeout(hideWhenIdle, CHROME_IDLE_MS)
        return
      }
      timerRef.current = null
      setHidden(true)
    }, CHROME_IDLE_MS)
  }, [chromeInUse, clear])

  const show = useCallback(() => {
    setHidden(false)
    scheduleHide()
  }, [scheduleHide])

  // Entering fullscreen starts the idle clock; leaving it restores chrome.
  useEffect(() => {
    if (!enabled) {
      clear()
      return
    }
    scheduleHide()
    return () => {
      clear()
      setHidden(false)
    }
  }, [clear, enabled, scheduleHide])

  const onPointerMove = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      if (!enabled) return
      const target = event.target as HTMLElement | null
      overChromeRef.current = Boolean(
        target?.closest?.('[data-book-preview-chrome]'),
      )
      if (event.pointerType !== 'mouse') return
      // A resting cursor in the page never wakes chrome — only real movement,
      // or approaching the edges where the bars live.
      if (event.movementX === 0 && event.movementY === 0) return
      const root = rootRef.current
      if (hidden && root) {
        const rect = root.getBoundingClientRect()
        const nearEdge =
          event.clientY - rect.top < EDGE_WAKE_PX ||
          rect.bottom - event.clientY < EDGE_WAKE_PX
        const brisk = Math.abs(event.movementX) + Math.abs(event.movementY) > 6
        if (!nearEdge && !brisk) return
      }
      show()
    },
    [enabled, hidden, rootRef, show],
  )

  const onPointerLeave = useCallback(() => {
    overChromeRef.current = false
  }, [])

  const onPointerDownCapture = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      if (!enabled || event.pointerType === 'mouse') return
      tapRef.current = {
        id: event.pointerId,
        x: event.clientX,
        y: event.clientY,
        t: event.timeStamp,
      }
    },
    [enabled],
  )

  // Touch and pen: a quick tap in the middle band of the page toggles chrome.
  // The outer bands belong to page turns, so they never toggle it.
  const onPointerUpCapture = useCallback(
    (event: PointerEvent<HTMLElement>) => {
      const tap = tapRef.current
      tapRef.current = null
      if (!enabled || !tap || tap.id !== event.pointerId) return
      if (event.timeStamp - tap.t > TAP_MAX_MS) return
      if (
        Math.hypot(event.clientX - tap.x, event.clientY - tap.y) >
        TAP_MAX_TRAVEL_PX
      ) {
        return
      }
      const target = event.target as HTMLElement | null
      if (isInteractiveTarget(target)) return
      if (target?.closest?.('[data-book-preview-chrome]')) return
      // With the pen out, a tap is ink.
      if (target?.closest?.('[data-bp-ink-surface][data-active]')) return
      // A tap that made a text selection is selecting, not asking for chrome.
      const selection = window.getSelection?.()
      if (selection && !selection.isCollapsed) return
      const root = rootRef.current
      if (!root) return
      const rect = root.getBoundingClientRect()
      const ratio = (event.clientX - rect.left) / Math.max(rect.width, 1)
      if (ratio < 0.28 || ratio > 0.72) return
      if (hidden) {
        show()
      } else {
        clear()
        setHidden(true)
      }
    },
    [clear, enabled, hidden, rootRef, show],
  )

  return {
    chromeHidden: enabled && hidden,
    showChrome: show,
    chromeHandlers: {
      onPointerMove,
      onPointerLeave,
      onPointerDownCapture,
      onPointerUpCapture,
    },
  }
}

'use client'

import { useSyncExternalStore } from 'react'
import { readUrlParam } from '../url-state'

const noopSubscribe = () => () => {}

/**
 * A query param as it stood when the page loaded, read during render. The
 * server snapshot is null, so hydration matches the server markup and the
 * client re-renders with the real value — no setState-in-effect round trip.
 * Later replaceState writes do not notify; callers keep their own state once
 * the reader makes a choice.
 */
export function useUrlParam(key: string | undefined): string | null {
  return useSyncExternalStore(
    noopSubscribe,
    () => readUrlParam(key),
    () => null,
  )
}

'use client'

import {
  useCallback,
  useEffect,
  useMemo,
  useState,
  useSyncExternalStore,
} from 'react'
import {
  annotationsStorageKey,
  sanitizeAnnotations,
  type BookPreviewAnnotation,
} from '../annotations'

const noopSubscribe = () => () => {}
const EMPTY: BookPreviewAnnotation[] = []

function readStored(sourceKey: string): BookPreviewAnnotation[] | undefined {
  try {
    const raw = window.localStorage.getItem(annotationsStorageKey(sourceKey))
    return raw === null ? undefined : sanitizeAnnotations(JSON.parse(raw))
  } catch {
    return undefined
  }
}

function writeStored(sourceKey: string, list: BookPreviewAnnotation[]) {
  try {
    window.localStorage.setItem(
      annotationsStorageKey(sourceKey),
      JSON.stringify(list),
    )
  } catch {
    // Storage may be full or unavailable (private mode) — the session copy
    // still works.
  }
}

/**
 * The notebook for the current document: controlled (`annotations` +
 * `onAnnotationsChange`, for hosts that sync to their own backend) or
 * uncontrolled, optionally remembered per document in localStorage and kept
 * in step across tabs through the storage event.
 */
export function useAnnotations({
  sourceKey,
  annotations,
  defaultAnnotations,
  onAnnotationsChange,
  persist,
}: {
  sourceKey: string
  annotations: BookPreviewAnnotation[] | undefined
  defaultAnnotations: BookPreviewAnnotation[] | undefined
  onAnnotationsChange: ((next: BookPreviewAnnotation[]) => void) | undefined
  persist: boolean
}) {
  const controlled = annotations !== undefined
  const hydrated = useSyncExternalStore(
    noopSubscribe,
    () => true,
    () => false,
  )
  // Bumped when another tab writes this document's notebook.
  const [storageVersion, setStorageVersion] = useState(0)
  const stored = useMemo(
    () =>
      persist && hydrated && storageVersion >= 0
        ? readStored(sourceKey)
        : undefined,
    [hydrated, persist, sourceKey, storageVersion],
  )
  // Session edits, tagged with the document they belong to so switching
  // documents never shows another book's highlights.
  const [local, setLocal] = useState<{
    key: string
    version: number
    list: BookPreviewAnnotation[]
  } | null>(null)

  useEffect(() => {
    if (!persist) return
    const storageKey = annotationsStorageKey(sourceKey)
    const onStorage = (event: StorageEvent) => {
      if (event.key === storageKey) setStorageVersion((v) => v + 1)
    }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [persist, sourceKey])

  const value: BookPreviewAnnotation[] = controlled
    ? annotations
    : local && local.key === sourceKey && local.version === storageVersion
      ? local.list
      : (stored ?? defaultAnnotations ?? EMPTY)

  const update = useCallback(
    (fn: (list: BookPreviewAnnotation[]) => BookPreviewAnnotation[]) => {
      const next = fn(value)
      if (!controlled) {
        setLocal({ key: sourceKey, version: storageVersion, list: next })
      }
      if (persist && !controlled) writeStored(sourceKey, next)
      onAnnotationsChange?.(next)
    },
    [
      controlled,
      onAnnotationsChange,
      persist,
      sourceKey,
      storageVersion,
      value,
    ],
  )

  return { annotations: value, updateAnnotations: update }
}

