type Turn = {
  id: number
  question: string
  answer: string
  status: 'streaming' | 'done' | 'error' | 'stopped'
}

function AskPanel({ ai }: { ai: BookPreviewAiAdapter }) {
  const { companion, state, source, getPageText } = useBookPreview()
  const seed = companion.askSeed
  const [available, setAvailable] = useState<boolean | null>(
    ai.isAvailable ? null : true,
  )
  const [question, setQuestion] = useState('')
  const [turns, setTurns] = useState<Turn[]>([])
  const abortRef = useRef<AbortController | null>(null)
  const scrollRef = useRef<HTMLDivElement | null>(null)
  const inputRef = useRef<HTMLTextAreaElement | null>(null)

  // A new "Ask about this" starts a fresh thread about that passage.
  const [seenNonce, setSeenNonce] = useState(seed?.nonce)
  if (seed?.nonce !== seenNonce) {
    setSeenNonce(seed?.nonce)
    setTurns([])
  }
  const selection = seed?.selection
  const pageIndex = seed?.pageIndex ?? state.pageIndex

  useEffect(() => {
    if (!ai.isAvailable) return
    let cancelled = false
    void Promise.resolve(ai.isAvailable()).then(
      (ok) => {
        if (!cancelled) setAvailable(ok)
      },
      () => {
        if (!cancelled) setAvailable(false)
      },
    )
    return () => {
      cancelled = true
    }
  }, [ai])

  useEffect(() => () => abortRef.current?.abort(), [])

  useEffect(() => {
    inputRef.current?.focus()
  }, [seed?.nonce])

  const ask = useCallback(
    async (text: string) => {
      const trimmed = text.trim()
      if (!trimmed) return
      abortRef.current?.abort()
      const controller = new AbortController()
      abortRef.current = controller
      const id = Date.now()
      setQuestion('')
      setTurns((list) => [
        ...list,
        { id, question: trimmed, answer: '', status: 'streaming' },
      ])
      const patch = (next: Partial<Turn>) =>
        setTurns((list) =>
          list.map((turn) => (turn.id === id ? { ...turn, ...next } : turn)),
        )
      try {
        await streamAnswer(
          ai.ask(
            {
              question: trimmed,
              selection,
              pageIndex,
              pageText: getPageText(pageIndex),
              title: source.title ?? source.pdfFileName,
              author: source.author,
            },
            { signal: controller.signal },
          ),
          (answer) => {
            if (!controller.signal.aborted) patch({ answer })
          },
        )
        if (!controller.signal.aborted) patch({ status: 'done' })
      } catch (error) {
        if (controller.signal.aborted) {
          patch({ status: 'stopped' })
          return
        }
        patch({
          status: 'error',
          answer:
            error instanceof Error ? error.message : 'The assistant failed.',
        })
      }
    },
    [ai, getPageText, pageIndex, selection, source],
  )

  // Keep the newest answer in view while it streams.
  const lastAnswer = turns[turns.length - 1]?.answer
  useEffect(() => {
    const el = scrollRef.current
    if (el) el.scrollTop = el.scrollHeight
  }, [lastAnswer, turns.length])

  const streaming = turns.some((turn) => turn.status === 'streaming')

  if (available === false) {
    return (
      <Empty className="flex-1 border-none">
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <IconSparkles />
          </EmptyMedia>
          <EmptyTitle>{ai.label} isn&apos;t available here</EmptyTitle>
          <EmptyDescription>
            This browser can&apos;t run it. The notebook still works — and the
            host can add a server-backed assistant as a fallback.
          </EmptyDescription>
        </EmptyHeader>
      </Empty>
    )
  }

  return (
    <>
      <div
        ref={scrollRef}
        className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto overscroll-contain px-4 pt-3 pb-2"
        aria-live="polite"
      >
        <div className="bg-muted/50 rounded-lg border p-3 text-xs">
          <p className="text-muted-foreground mb-1 font-medium">
            About page {pageIndex + 1}
          </p>
          {selection ? (
            <p className="line-clamp-4 font-serif text-sm leading-relaxed">
              “{selection}”
            </p>
          ) : (
            <p className="text-muted-foreground">
              Ask about anything on this page, or select a passage first.
            </p>
          )}
        </div>
        {turns.length === 0 ? (
          <div className="flex flex-wrap gap-1.5">
            {ASK_QUICK_PROMPTS.map((prompt) => (
              <Button
                key={prompt.label}
                type="button"
                variant="outline"
                size="xs"
                disabled={available === null}
                onClick={() => void ask(prompt.question)}
                data-book-preview-press
              >
                {prompt.label}
              </Button>
            ))}
          </div>
        ) : null}
        {turns.map((turn) => (
          <div key={turn.id} className="flex flex-col gap-1.5">
            <p className="bg-primary text-primary-foreground self-end rounded-2xl rounded-br-md px-3 py-1.5 text-sm">
              {turn.question}
            </p>
            <div
              className={cn(
                'text-sm leading-relaxed whitespace-pre-wrap',
                turn.status === 'error' && 'text-destructive',
              )}
            >
              {turn.answer ||
                (turn.status === 'streaming' ? (
                  <span className="text-muted-foreground inline-flex items-center gap-2">
                    <Spinner />
                    Reading the page…
                  </span>
                ) : null)}
              {turn.status === 'stopped' ? (
                <span className="text-muted-foreground"> (stopped)</span>
              ) : null}
            </div>
          </div>
        ))}
      </div>
      <form
        className="flex items-end gap-2 border-t p-3"
        onSubmit={(event) => {
          event.preventDefault()
          void ask(question)
        }}
      >
        <textarea
          ref={inputRef}
          rows={1}
          value={question}
          aria-label="Ask about this page"
          placeholder={
            available === null
              ? 'Checking the assistant…'
              : 'Ask about this page…'
          }
          disabled={available === null}
          onChange={(event) => setQuestion(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter' && !event.shiftKey) {
              event.preventDefault()
              void ask(question)
            }
          }}
          className="border-input focus-visible:border-ring focus-visible:ring-ring/50 [field-sizing:content] max-h-32 min-h-9 flex-1 resize-none rounded-md border bg-transparent px-3 py-2 text-sm outline-none focus-visible:ring-[3px]"
        />
        {streaming ? (
          <Button
            type="button"
            size="icon-sm"
            variant="secondary"
            aria-label="Stop"
            onClick={() => abortRef.current?.abort()}
            data-book-preview-press
          >
            <IconPlayerStopFilled />
          </Button>
        ) : (
          <Button
            type="submit"
            size="icon-sm"
            aria-label="Ask"
            disabled={!question.trim() || available === null}
            data-book-preview-press
          >
            <IconArrowUp />
          </Button>
        )}
      </form>
      <p className="text-muted-foreground px-4 pb-3 text-[11px]">
        {ai.label} · answers can be wrong — check them against the page.
      </p>
    </>
  )
}

'use client'

import { findBookmark } from './annotations'
import { useBookPreview } from './book-preview-provider'

/** A silk ribbon on the top edge of a bookmarked page — the quiet, physical
    answer to "did I mark this?". Decorative; the toolbar button and the
    notebook carry the state for assistive tech. */
export function BookPreviewBookmarkRibbon() {
  const { annotations, state } = useBookPreview()
  if (state.status !== 'ready' || state.totalPages === 0) return null
  const bookmark = findBookmark(annotations, state.pageIndex)
  if (!bookmark) return null
  return (
    <div
      key={bookmark.id}
      aria-hidden
      data-book-preview-ribbon
      className="pointer-events-none absolute top-0 right-6 z-30 h-9 w-5 shadow-md"
      style={{
        // Silk-ribbon red reads on every paper — white, sepia, and night.
        background: 'var(--book-preview-ribbon, oklch(0.56 0.19 25))',
        clipPath: 'polygon(0 0, 100% 0, 100% 100%, 50% 78%, 0 100%)',
      }}
    />
  )
}

/**
 * Freehand ink — the pure half. Strokes live in page-relative coordinates
 * (0–1 on both axes) with a width relative to the page width, so a drawing
 * made on a phone lands in the same place, at the same weight, on a 4K
 * monitor or at 240% zoom. No DOM here; bun tests it directly.
 */

export const INK_COLORS = ['ink', 'red', 'blue', 'green', 'yellow'] as const
export type BookPreviewInkColor = (typeof INK_COLORS)[number]

export const INK_TOOLS = ['pen', 'marker', 'eraser'] as const
export type BookPreviewInkTool = (typeof INK_TOOLS)[number]

/** Stroke width as a fraction of the page width. */
export const INK_WIDTHS = { pen: 0.0035, marker: 0.022 } as const

/** Minimum travel between kept samples, in page-width fractions — drops the
    jitter of a resting stylus without flattening curves. */
export const INK_MIN_STEP = 0.0015

/** Coordinates are rounded to this many decimals when stored: sub-pixel on
    any real screen, and a stroke stays a few hundred bytes. */
const PRECISION = 4

export type InkPoint = { x: number; y: number }

const round = (value: number) => {
  const factor = 10 ** PRECISION
  return Math.round(value * factor) / factor
}

const clamp01 = (value: number) => Math.min(1, Math.max(0, value))

/** Page-relative point from a client position and the page's rect. */
export function toPagePoint(
  clientX: number,
  clientY: number,
  rect: { left: number; top: number; width: number; height: number },
): InkPoint {
  return {
    x: clamp01((clientX - rect.left) / Math.max(rect.width, 1)),
    y: clamp01((clientY - rect.top) / Math.max(rect.height, 1)),
  }
}

/** Appends a sample unless it is closer than `minStep` to the last kept one
    (measured in page-width units so it is aspect-independent). Returns
    whether it was kept. */
export function pushInkPoint(
  points: InkPoint[],
  next: InkPoint,
  aspect: number,
  minStep = INK_MIN_STEP,
): boolean {
  const last = points[points.length - 1]
  if (last) {
    const dx = next.x - last.x
    const dy = (next.y - last.y) / Math.max(aspect, 0.01)
    if (Math.hypot(dx, dy) < minStep) return false
  }
  points.push(next)
  return true
}

/** Flat [x0, y0, x1, y1, …] rounded for storage. */
export function flattenInk(points: readonly InkPoint[]): number[] {
  const out: number[] = []
  for (const point of points) out.push(round(point.x), round(point.y))
  return out
}

export function unflattenInk(flat: readonly number[]): InkPoint[] {
  const out: InkPoint[] = []
  for (let index = 0; index + 1 < flat.length; index += 2) {
    out.push({ x: flat[index], y: flat[index + 1] })
  }
  return out
}

/**
 * A smooth SVG path through the samples in a `width × height` box: straight
 * to the first midpoint, then quadratic curves through each sample to the
 * next midpoint — the classic midpoint-smoothing that makes a stylus line
 * look inked rather than plotted. A single tap becomes a dot.
 */
export function inkPath(
  points: readonly InkPoint[],
  width: number,
  height: number,
): string {
  if (points.length === 0) return ''
  const p = (point: InkPoint) =>
    `${(point.x * width).toFixed(2)} ${(point.y * height).toFixed(2)}`
  if (points.length === 1) {
    // Zero-length segment with a round cap renders as a dot.
    return `M ${p(points[0])} l 0.01 0`
  }
  if (points.length === 2) return `M ${p(points[0])} L ${p(points[1])}`
  let d = `M ${p(points[0])}`
  for (let index = 1; index < points.length - 1; index += 1) {
    const current = points[index]
    const next = points[index + 1]
    const mid = { x: (current.x + next.x) / 2, y: (current.y + next.y) / 2 }
    d += ` Q ${p(current)} ${p(mid)}`
  }
  d += ` L ${p(points[points.length - 1])}`
  return d
}

function distanceToSegment(
  point: InkPoint,
  a: InkPoint,
  b: InkPoint,
  aspect: number,
): number {
  // Work in page-width units on both axes so the eraser is round.
  const scaleY = 1 / Math.max(aspect, 0.01)
  const px = point.x
  const py = point.y * scaleY
  const ax = a.x
  const ay = a.y * scaleY
  const bx = b.x
  const by = b.y * scaleY
  const dx = bx - ax
  const dy = by - ay
  const lengthSq = dx * dx + dy * dy
  const t =
    lengthSq === 0
      ? 0
      : Math.min(1, Math.max(0, ((px - ax) * dx + (py - ay) * dy) / lengthSq))
  return Math.hypot(px - (ax + t * dx), py - (ay + t * dy))
}

/**
 * Whether an eraser at `point` (radius in page-width units) touches a stroke.
 * `aspect` is page width / height, so the hit area stays circular on tall
 * and wide pages alike.
 */
export function inkHit(
  flat: readonly number[],
  strokeWidth: number,
  point: InkPoint,
  radius: number,
  aspect: number,
): boolean {
  const points = unflattenInk(flat)
  const reach = radius + strokeWidth / 2
  if (points.length === 1) {
    return distanceToSegment(point, points[0], points[0], aspect) <= reach
  }
  for (let index = 1; index < points.length; index += 1) {
    if (
      distanceToSegment(point, points[index - 1], points[index], aspect) <=
      reach
    ) {
      return true
    }
  }
  return false
}

export const INK_SWATCHES: Record<
  BookPreviewInkColor,
  { label: string; stroke: string }
> = {
  // "Ink" follows the page's text colour, so it reads on any paper.
  ink: { label: 'Ink', stroke: 'currentColor' },
  red: { label: 'Red', stroke: 'rgb(220 38 38)' },
  blue: { label: 'Blue', stroke: 'rgb(37 99 235)' },
  green: { label: 'Green', stroke: 'rgb(22 163 74)' },
  yellow: { label: 'Yellow', stroke: 'rgb(234 179 8)' },
}

